module('let.c', function(require, ...)
-- C output vocabulary, not a second semantic/residual IR. No Let ownership or specialization.
return function(context)
    context:Define [[
module C {
    Type = Void | Bool | I64 | F64 | U64 | U8 | Size
         | Pointer(Type pointee) | Named(string name)
    Expr = Integer(number hi, number lo) | Float(number value) | Boolean(boolean value) | String(string value)
         | Name(string name) | Unary(string operator, Expr operand)
         | Binary(string operator, Expr left, Expr right)
         | Cast(Type type, Expr value) | Call(Expr callee, Expr* arguments)
         | Field(Expr base, string name) | Index(Expr base, Expr index)
         | Compound(Type type, Expr* fields)
    Parameter = (Type type, string name)
    Stmt = Declare(Type type, string name, Expr? initial)
         | Assign(Expr place, Expr value) | Evaluate(Expr value)
         | Block(Stmt* statements) | If(Expr condition, Stmt yes, Stmt? no)
         | While(Expr condition, Stmt body)
         | Label(string name) | Goto(string name) | Return(Expr? value)
    Declaration = Function(string name, boolean external, boolean exported, Type result, Parameter* parameters, Stmt? body)
                | Struct(string name, Parameter* fields)
                | Raw(string code)
                | Global(Type type, string name)
    Unit = (string* includes, Declaration* declarations)
}
    ]]
end


end)

-- let/contract.lua
module('let.contract', function(require, ...)
-- A template's contract: the interface construction needs before it builds a body.
--
-- Annotations are not a language requirement (§4.1, §6.3), but a host entry needs a concrete
-- parameter type to publish and a self-call needs the word's result type before the return that
-- states it has been built. This pass answers both by reading the terminal body and the
-- preparation regions, so the interface of a template does not depend on the order construction
-- happens to walk it.
--
-- It is deliberately conservative. It records a type only when the source forces exactly one: an
-- operator's other operand is a literal, a host stage declares the parameter, a conversion fixes
-- it, a word-valued callee's stage declares it, an aggregate member that the surrounding type
-- matches, or an alias carries a forced initializer. Anything ambiguous -- `x + y` with no other
-- constraint, `return x` alone, a word-typed stage with no call -- yields no type, and the
-- builder keeps its existing outcome. It never rejects; construction still checks what it is
-- given.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
local scalar=require('let.scalar')

local Contract={}

local function numeric(type_) return type_==B.Int or type_==B.Float end

-- The definition a resolved name node refers to, or nil for a literal or an unresolved form.
local function definition_of(resolved,node)
    local references=resolved.references[node]
    local use=references and references[1]
    return use and use.definition
end

-- The concrete belt type a constraint names. `Copy` and `Executable` describe a shape, not a
-- type, so they name none; the builder reports that separately.
local function constraint_type(types,constraint)
    if not constraint then return nil end
    return types[constraint.name]
end

-- A written integer index, or nil when the index is only known at run time. `-7` is a unary
-- negation of a literal, so both spellings are recognized (§2.2).
local function static_index(expr)
    local negative=A.Unary:isclassof(expr) and expr.operator==A.Negate
    local operand=negative and expr.operand or expr
    if not A.Integer:isclassof(operand) then return nil end
    local value=tonumber(scalar.integer(operand.spelling,function(message) error(message,0) end))
    return negative and -value or value
end

-- One template's contract, computed once per template. A cycle returns no interface rather than
-- recursing: a word that calls itself through another word simply keeps the conservative outcome.
local memo=setmetatable({},{__mode='k'})

local function compute(template,resolved,types,environment)
    local inferred={}      -- stage definition -> Belt.Type, or false once two uses disagree
    local initializer={}   -- binding definition -> its initializer Chain
    local stated,returns,conflict=nil,0,false

    -- A stage is recorded only once, and only toward one type. A disagreement is a program the
    -- builder will reject anyway, so it just means "no usable type here".
    local function record(definition,type_)
        if not definition or not type_ then return nil end
        local was=inferred[definition]
        if was==nil then inferred[definition]=type_; return type_ end
        if was==false or not was:same(type_) then inferred[definition]=false; return nil end
        return type_
    end

    local function infer_binding(binding)
        -- An initializer fixes the binding's type whether or not it is mutable: assignment
        -- must match that type, so the alias still carries it to a later use.
        local definition=resolved.bindings[binding]
        if definition then initializer[definition]=binding.value end
    end

    local infer, statements, chain

    -- The template a callee names, when the callee is a word rather than a data value. A
    -- specialization (`let double = scale 2`) has a data terminal and no stages of its own, so
    -- its remaining stages are not visible here and it yields no interface.
    local function callee_template(definition)
        local callee=definition and definition.template
        if not callee then return nil end
        if #callee.steps==0 and not A.Body:isclassof(callee.source.terminal) then return nil end
        return callee
    end

    -- The stage type a callee's argument fills. `index` is the 1-based stage position.
    local function callee_stage(callee,contract,index)
        local step=callee.steps[index]
        if not step then return nil end
        return constraint_type(types,step.stage.constraint) or contract.stages[resolved.bindings[step.stage]]
    end

    -- The type of `expr`, recording a forced type on any stage name it reaches. `expected` is
    -- what the surrounding form requires of this expression, or nil when nothing does.
    function infer(expr,expected)
        if not expr then return nil end
        if A.Integer:isclassof(expr) then return B.Int end
        if A.Float:isclassof(expr) then return B.Float end
        if A.Boolean:isclassof(expr) then return B.Bool end
        if A.Text:isclassof(expr) then return B.Text end
        if A.Unit:isclassof(expr) then return B.Unit end
        if A.Name:isclassof(expr) then
            local definition=definition_of(resolved,expr)
            if not definition then return nil end
            if definition.kind=='stage' then
                if expected then return record(definition,expected) end
                local known=inferred[definition]
                return known~=false and known or nil
            end
            -- A capture's type comes from the packet the entry was handed, not from this body.
            local captured=environment[definition]
            if captured then return captured end
            -- `let y = x` is an alias of the same value, so a use of `y` constrains `x`.
            local value=initializer[definition]
            if value and #value.items==0 and A.Data:isclassof(value.terminal) then
                return infer(value.terminal.value,expected)
            end
            return nil
        end
        if A.Move:isclassof(expr) then return infer(expr.place,expected) end
        if A.Unary:isclassof(expr) then
            local operator=expr.operator
            if operator==A.Not then infer(expr.operand,B.Bool); return B.Bool end
            if operator==A.ToFloat then infer(expr.operand,B.Int); return B.Float end
            if operator==A.ToInt then infer(expr.operand,B.Float); return B.Int end
            -- Negate: the operand has the expression's type.
            local type_=infer(expr.operand,expected)
            if type_ then return type_ end
            if numeric(expected) then infer(expr.operand,expected); return expected end
            return nil
        end
        if A.Binary:isclassof(expr) then
            local operator=expr.operator
            if operator==A.And or operator==A.Or then
                infer(expr.left,B.Bool); infer(expr.right,B.Bool); return B.Bool
            end
            if operator==A.Equal or operator==A.NotEqual then
                local type_=expected or infer(expr.left,nil) or infer(expr.right,nil)
                if type_ then infer(expr.left,type_); infer(expr.right,type_) end
                return B.Bool
            end
            -- Comparison and arithmetic both require one numeric type on both sides.
            local type_=(numeric(expected) and expected) or infer(expr.left,nil) or infer(expr.right,nil)
            if type_ and numeric(type_) then infer(expr.left,type_); infer(expr.right,type_) end
            if operator==A.Less or operator==A.LessEqual or operator==A.Greater or operator==A.GreaterEqual then
                return B.Bool
            end
            return type_ and numeric(type_) and type_ or nil
        end
        -- A record the surrounding type already describes: each member takes the member type.
        if A.PositionalAggregate:isclassof(expr) then
            local wanted=expected and expected:record()
            local declared,complete,copy=L(),true,true
            for i,element in ipairs(expr.elements) do
                local type_=chain(element,wanted and wanted[i] and wanted[i].type)
                if not type_ then complete=false
                else
                    declared:insert(B.Field(nil,type_,false))
                    if not type_:copyable() then copy=false end
                end
            end
            if not complete then return nil end
            return B.Aggregate(declared,copy)
        end
        if A.NamedAggregate:isclassof(expr) then
            local wanted=expected and expected:record()
            local declared,complete,copy=L(),true,true
            for _,member in ipairs(expr.members) do
                local member_type
                if wanted then for _,field in ipairs(wanted) do if field.name==member.name then member_type=field.type end end end
                local type_=constraint_type(types,member.constraint) or chain(member.value,member_type)
                if not type_ then complete=false
                else
                    declared:insert(B.Field(member.name,type_,member.mutable))
                    if member.mutable or not type_:copyable() then copy=false end
                end
            end
            if not complete then return nil end
            return B.Aggregate(declared,copy)
        end
        if A.Project:isclassof(expr) then
            local base=infer(expr.base,nil)
            local fields=base and base:record()
            if fields then
                for _,field in ipairs(fields) do if field.name==expr.name then return field.type end end
            end
            return nil
        end
        if A.Index:isclassof(expr) then
            local base=infer(expr.base,nil)
            local fields=base and base:record()
            if not fields then return nil end
            local index=static_index(expr.index)
            if index then
                local field=fields[index+1]
                return field and field.type or nil
            end
            -- A run-time index yields one value, so the members must share one type.
            infer(expr.index,B.Int)
            local element=fields[1] and fields[1].type
            for i=2,#fields do if not fields[i].type:same(element) then return nil end end
            return element
        end
        -- A named callee: a conversion, a registered host, or a word whose contract types the
        -- arguments. A word's own result type is known when its contract could compute one.
        if A.Invoke:isclassof(expr) and A.Name:isclassof(expr.word) then
            local definition=definition_of(resolved,expr.word)
            if definition and definition.kind=='dictionary' then
                -- The core conversions (§13.3) fix their argument and their result.
                if definition.name=='float' then infer(expr.arguments[1],B.Int); return B.Float end
                if definition.name=='int' then infer(expr.arguments[1],B.Float); return B.Int end
                local host=definition.node
                local signature=host and host.signature
                if signature then
                    for i,argument in ipairs(expr.arguments) do
                        local parameter=signature.parameters[i]
                        if parameter then infer(argument,parameter.type) end
                    end
                    return signature.results[1]
                end
                return nil
            end
            local callee=callee_template(definition)
            if not callee then return nil end
            local contract=Contract.template(callee,resolved,types,nil)
            for i,argument in ipairs(expr.arguments) do infer(argument,callee_stage(callee,contract,i)) end
            return contract.result
        end
        -- Juxtaposition: a conversion, or the next stage of a word. The result is the more
        -- specific word value, whose type this pass does not model.
        if A.Specialize:isclassof(expr) and A.Name:isclassof(expr.word) then
            local definition=definition_of(resolved,expr.word)
            if definition and definition.kind=='dictionary' then
                if definition.name=='float' then infer(expr.argument,B.Int); return B.Float end
                if definition.name=='int' then infer(expr.argument,B.Float); return B.Int end
                return nil
            end
            local callee=callee_template(definition)
            if callee then
                local contract=Contract.template(callee,resolved,types,nil)
                infer(expr.argument,callee_stage(callee,contract,1))
            end
            return nil
        end
        return nil
    end

    function chain(chain,expected)
        if chain and #chain.items==0 and A.Data:isclassof(chain.terminal) then
            return infer(chain.terminal.value,expected)
        end
        return nil
    end

    -- A return states the result type. Every return must agree; one the pass cannot type is
    -- simply absent, and a returned self-call is the case that stays unknown.
    local function returned(statement)
        returns=returns+1
        local type_
        if statement.value then type_=infer(statement.value,nil) else type_=B.Unit end
        if type_ then
            if stated==nil then stated=type_
            elseif not stated:same(type_) then conflict=true end
        end
    end

    statements=function(list)
        for _,statement in ipairs(list) do
            if A.Local:isclassof(statement) then
                infer_binding(statement.binding); chain(statement.binding.value,constraint_type(types,statement.binding.constraint))
            elseif A.Assign:isclassof(statement) then
                -- The place's type is the expectation for the value, which is how `y = x`
                -- constrains a stage `x` once `y` is typed.
                local place_type=A.Name:isclassof(statement.place) and infer(statement.place,nil) or nil
                local type_=infer(statement.value,place_type)
                if A.Name:isclassof(statement.place) then record(definition_of(resolved,statement.place),type_) end
            elseif A.Return:isclassof(statement) then
                returned(statement)
            elseif A.Discard:isclassof(statement) then
                infer(statement.value,nil)
            elseif A.If:isclassof(statement) then
                infer(statement.condition,B.Bool); statements(statement.yes); statements(statement.no)
            elseif A.While:isclassof(statement) then
                infer(statement.condition,B.Bool); statements(statement.body)
            elseif A.Switch:isclassof(statement) then
                -- Case labels must be Int or Bool literals (§7.2), so a subject that names a
                -- stage takes that type.
                local label_type
                for _,arm in ipairs(statement.cases) do
                    for _,label in ipairs(arm.labels) do
                        if A.Boolean:isclassof(label) then label_type=label_type or B.Bool
                        else label_type=label_type or B.Int end
                    end
                end
                infer(statement.subject,label_type)
                for _,arm in ipairs(statement.cases) do statements(arm.body) end
                statements(statement.otherwise)
            end
        end
    end

    -- The chain items in source order, then the terminal: a prelude may use an earlier stage,
    -- and the terminal may use any of them.
    for _,item in ipairs(template.source.items) do
        if A.Prelude:isclassof(item) then
            infer_binding(item.binding); chain(item.binding.value,constraint_type(types,item.binding.constraint))
        end
    end
    local terminal=template.source.terminal
    local result
    if A.Body:isclassof(terminal) then
        statements(terminal.statements)
        result=conflict and nil or (returns==0 and B.Unit or stated)
    elseif A.Data:isclassof(terminal) then
        infer(terminal.value,nil)
    end

    local stages={}
    for definition,type_ in pairs(inferred) do if type_ then stages[definition]=type_ end end
    return {stages=stages,result=result}
end

-- A template's contract. `environment` maps a binding to the type the entry packet gave it, so
-- the result a return states can be computed where those types are known. A contract computed
-- without one is remembered, because it describes the template rather than one packet.
function Contract.template(template,resolved,types,environment)
    local general=environment==nil or next(environment)==nil
    if general then
        local cached=memo[template]
        if cached==false then return {stages={},result=nil} end
        if cached then return cached end
        memo[template]=false
    end
    local contract=compute(template,resolved,types,environment or {})
    if general then memo[template]=contract end
    return contract
end

return Contract
end

end)

-- let/scalar.lua
module('let.scalar', function(require, ...)
-- Exact scalar semantics, shared by the concrete test interpreter and the abstract
-- evaluator so the two cannot drift.
--
-- LuaJIT's 64-bit cdata arithmetic is already the behavior §13.2 requires: wrapping
-- +,-,*; quotient truncated toward zero; remainder with the dividend's sign; and
-- INT_MIN / -1 wrapping to INT_MIN with INT_MIN % -1 equal to zero.
local ffi=require('ffi')
local literal=require('let.literal')
local M={}

M.min=ffi.cast('int64_t',0x8000000000000000ULL)
M.unit={}

-- Validates spelling and range, then converts without passing through a Lua number.
function M.integer(spelling,fail)
    local negative=spelling:sub(1,1)=='-'
    local _,_,hi,lo=literal.integer(negative and spelling:sub(2) or spelling,negative,fail or error)
    local magnitude=ffi.cast('uint64_t',hi)*4294967296ULL+lo
    return negative and -ffi.cast('int64_t',magnitude) or ffi.cast('int64_t',magnitude)
end

-- A Float value is a Lua number (a binary64), and this conversion is the one authority for
-- both folding and C emission, so the two cannot round differently.
function M.float(spelling,fail) return literal.float(spelling,fail or error) end

function M.fdivide(a,b) return a/b end

-- The two core conversions. `to_float` is total; `to_int` is also total, truncating toward
-- zero and saturating at the Int bounds with a NaN becoming zero, so it stays a pure value
-- operation that can be folded and dropped. One definition serves folding and the test
-- interpreter; the C helper mirrors it.
function M.to_float(value) return tonumber(value) end
function M.to_int(value)
    if value~=value then return ffi.new('int64_t',0) end
    if value>=9223372036854775808.0 then return ffi.cast('int64_t',0x7fffffffffffffffULL) end
    if value<-9223372036854775808.0 then return ffi.cast('int64_t',0x8000000000000000ULL) end
    return ffi.new('int64_t',value)
end

function M.add(a,b) return a+b end
function M.subtract(a,b) return a-b end
function M.multiply(a,b) return a*b end
function M.negate(a) return -a end

-- Division and remainder by zero trap; callers either know the divisor is non-zero
-- (and fold) or must keep a residual checked operation.
function M.divide(a,b)
    if b==0 then error('division by zero') end
    return a/b
end
function M.remainder(a,b)
    if b==0 then error('remainder by zero') end
    return a%b
end

function M.equal(a,b) return a==b end
function M.not_equal(a,b) return a~=b end
function M.less(a,b) return a<b end
function M.less_equal(a,b) return a<=b end
function M.greater(a,b) return a>b end
function M.greater_equal(a,b) return a>=b end

-- Two's-complement limbs for C emission.
function M.limbs(value)
    local unsigned=ffi.cast('uint64_t',value)
    return tonumber(unsigned/4294967296ULL),tonumber(unsigned%4294967296ULL)
end

-- The byte length of a Text, shared so a known Text folds and the emitted C reads `.size`.
function M.text_size(value) return #value end

return M

end)

-- let/literal.lua
module('let.literal', function(require, ...)
-- Validate spelling/range without passing a 64-bit integer through a Lua number.
local M={}
function M.integer(spelling,negative,fail)
    local base,body=10,spelling
    if body:sub(1,2)=='0x' then base,body=16,body:sub(3) end
    local digits=body:gsub('_','')
    if body=='' or body:sub(1,1)=='_' or body:sub(-1)=='_' or body:find('__',1,true) or
       not digits:match(base==16 and '^[0-9a-fA-F]+$' or '^[0-9]+$') then fail('invalid integer spelling') end
    local hi,lo=0,0
    for digit in digits:gmatch('.') do
        local next_=lo*base+tonumber(digit,base)
        lo,hi=next_%4294967296,hi*base+math.floor(next_/4294967296)
        if hi>2147483648 or (hi==2147483648 and (lo~=0 or not negative)) then fail('integer literal out of Int range') end
    end
    local sign=negative and (hi~=0 or lo~=0) and '-' or ''
    return sign .. (base==16 and '0x' or '') .. digits,sign .. hi .. ':' .. lo,hi,lo
end
-- A Float literal: the grammar has a digit on each side of `.`, and an exponent carries at
-- least one digit. Value and C emission both take their bits from this one conversion, so
-- folding and execution cannot round differently.
local function digits(text)
    return text~='' and text:sub(1,1)~='_' and text:sub(-1)~='_' and not text:find('__',1,true)
        and text:match('^[0-9_]+$')~=nil
end
function M.float(spelling,fail)
    local mantissa,exponent=spelling,nil
    local at=spelling:find('[eE]')
    if at then
        mantissa=spelling:sub(1,at-1); exponent=spelling:sub(at+1)
        local sign=exponent:sub(1,1)
        if sign=='+' or sign=='-' then exponent=exponent:sub(2) end
        if not digits(exponent) then fail('invalid Float spelling') end
    end
    local point=mantissa:find('.',1,true)
    if point then
        if not digits(mantissa:sub(1,point-1)) or not digits(mantissa:sub(point+1)) then fail('invalid Float spelling') end
    elseif not digits(mantissa) then fail('invalid Float spelling') end
    if not point and not at then fail('invalid Float spelling') end
    local value=tonumber((spelling:gsub('_','')))
    if value==nil then fail('invalid Float spelling') end
    return value
end
return M


end)

-- let/packet.lua
module('let.packet', function(require, ...)
-- The word field packet: the ordered bundle of values a word carries between its stages, and
-- the one owner of what a field means.
--
-- A field descriptor is `{name, type, value, mutable, owned, retained, span}` plus whatever the
-- site knows: `capability` for a stage, `definition` for a prelude, `borrows` for a capture. The
-- derived questions -- is it a place, is it owned by the entry, is it written back, what is the
-- entry key -- live here, so the six sites that build a packet and the four that consume one do
-- not each restate them. See DESIGN.md.
return function(V)
local A,B=V.AST,V.Belt

local Packet={}

-- A field that reaches the callee as a place -- an address or a borrow -- is written through,
-- not copied. This is the one place the question is asked.
function Packet.place(type_) return B.Address:isclassof(type_) or B.Borrow:isclassof(type_) end

-- Normalize a descriptor: a site supplies what it knows, and the shared defaults live here.
function Packet.field(spec)
    spec.mutable=spec.mutable==true
    spec.owned=spec.owned==true
    spec.retained=spec.retained==true
    return spec
end

-- A field parameterized into an entry is owned by that entry when it is non-Copy, is not a place,
-- and the word already owned it or its stage takes ownership.
function Packet.entry_owned(field)
    if Packet.place(field.type) or field.type:copyable() then return false end
    return field.owned or field.capability==A.Own or field.capability==A.OwnMut
end

-- The type a stage delivers and who owns it. `mut` and `own mut` reach the callee as a place
-- through a borrow; `own` and `own mut` carry ownership. One rule, so the generic builder and a
-- host entry cannot disagree about what a stage delivers.
function Packet.stage_field(capability,name,span,type_)
    local place=capability==A.Mut or capability==A.OwnMut
    local owned=not type_:copyable() and (capability==A.Own or capability==A.OwnMut)
    return Packet.field{name=name,type=place and B.Borrow(type_,false) or type_,
        mutable=capability==A.Mut or capability==A.OwnMut,owned=owned,retained=false,
        span=span,capability=capability,external=place or (not owned and not type_:copyable())}
end

-- The parameter a host entry receives for a stage. The host supplies the value, so there is no
-- field packet here; the shape and the mode are all that matter.
function Packet.stage_parameter(ctx,capability,type_,span)
    local place=capability==A.Mut or capability==A.OwnMut
    local value=ctx:parameter(place and B.Borrow(type_,false) or type_,A.Read)
    if capability==A.Mut then value.mode='mut'
    elseif capability==A.Own or capability==A.OwnMut then value.mode='fresh' end
    return value
end

-- The fields an invocation hands back to the receiver: interior mutable state it can receive. A
-- place is written through the callee itself, so it is never a result.
function Packet.written_back(field)
    return field.mutable and field.retained and not B.Address:isclassof(field.type)
end

-- A word with any mutable retained field is stateful for tail-transfer purposes, whether the
-- state is written back as a value or reached through a place.
function Packet.mutable_state(field) return field.mutable and field.retained end

-- The entry a field packet names. One key per shape, so call sites that agree share one function
-- and its signature. The per-field flag runs are separate so a shape cannot collide with a longer
-- one that happens to reuse the same type keys.
function Packet.key(template_id,fields)
    local parts={tostring(template_id)}
    for _,field in ipairs(fields) do parts[#parts+1]=field.type:key() end
    for _,field in ipairs(fields) do parts[#parts+1]=field.retained and '1' or '0' end
    for _,field in ipairs(fields) do parts[#parts+1]=field.owned and '1' or '0' end
    return table.concat(parts,'|')
end

-- Bind a field the packet already holds, in the scope the caller opened. A place is bound as its
-- own storage, so the body reaches the caller's value rather than a copy.
function Packet.bind(ctx,field)
    local address=Packet.place(field.value.type) and field.value or false
    ctx:force_bind(field.name,field.value,field.mutable,field.owned,false,address,field.span)
end

function Packet.bind_all(ctx,fields)
    for _,field in ipairs(fields) do Packet.bind(ctx,field) end
end

-- Bind a field as a fresh parameter of an entry, in its own scope. An entry owns a non-Copy,
-- non-place field, and the parameter is what the caller's field becomes here. Returns the binding
-- id, the parameter value and the ownership the entry took, so a caller can record or trace it.
function Packet.bind_parameter(ctx,field,name,span)
    ctx:push(); if field.retained then ctx:retain() end
    local parameter=ctx:parameter(field.type,A.Read)
    if field.capability==A.Mut then parameter.mode='mut'
    elseif field.capability==A.Own or field.capability==A.OwnMut then parameter.mode='fresh' end
    local owned=Packet.entry_owned(field)
    local address=Packet.place(field.type) and parameter or false
    local binding=ctx:force_bind(name or field.name,parameter,field.mutable,owned,field.external==true,address,span or field.span)
    return binding,parameter,owned
end

return Packet
end

end)

-- let/vocabulary.lua
module('let.vocabulary', function(require, ...)
-- The names a program may refer to and the contracts behind them: the scalar types, the
-- registered resources with their destructors, and the runtime hosts. Validated once, so a call
-- site, an entry and the verifier cannot disagree about a descriptor, and no phase rebuilds the
-- base type table.
return function(V)
local B=V.Belt

local Vocabulary={}; Vocabulary.__index=Vocabulary

-- One validated vocabulary for a program. A descriptor that is malformed fails here, with the
-- message naming the contract, rather than at whichever consumer happened to read it first.
function Vocabulary.new(options)
    options=options or {}
    local types={Int=B.Int,Float=B.Float,Bool=B.Bool,Unit=B.Unit,Text=B.Text,CString=B.CString,CPointer=B.CPointer}
    local representations={}
    local destroy={}
    for name,descriptor in pairs(options.resources or {}) do
        assert(type(descriptor.destroy)=='string' and descriptor.destroy:match('^[A-Za-z_][A-Za-z0-9_]*$'),
            'resource requires a destructor symbol')
        if descriptor.representation~=nil then
            assert(descriptor.representation=='pointer' or descriptor.representation=='value',
                'resource representation must be pointer or value')
        end
        types[name]=B.Named(name)
        destroy[name]=descriptor.destroy
        representations[name]=descriptor.representation or 'value'
    end
    local hosts={}
    local symbols={}
    -- The C spelling a host declares must describe its Let type: an integer width for `Int` or a
    -- value resource, an object pointer for a borrowed view or a pointer resource, and
    -- `double`/`bool`/`void` for the rest. This is where the one declaration is checked, rather
    -- than in the C compiler.
    local function compact(name) return (name:gsub('%s','')) end
    local c_integer={}
    for _,name in ipairs{'char','signedchar','unsignedchar','short','unsignedshort','int','unsigned',
        'long','unsignedlong','longlong','unsignedlonglong','size_t','ssize_t','ptrdiff_t','intptr_t',
        'uintptr_t','int8_t','uint8_t','int16_t','uint16_t','int32_t','uint32_t','int64_t','uint64_t'} do
        c_integer[name]=true
    end
    local function c_kind(spelling)
        local c=compact(spelling)
        if c_integer[c] then return 'integer' end
        if c=='double' or c=='float' then return c end
        if c=='bool' or c=='_Bool' then return 'bool' end
        if c=='void' then return 'void' end
        if c:sub(-1)=='*' then return 'pointer' end
        return 'unknown'
    end
    local function compatible(let_type,kind)
        if kind=='integer' then
            return let_type==B.Int or (B.Named:isclassof(let_type) and representations[let_type.name]~='pointer')
        end
        if kind=='double' or kind=='float' then return let_type==B.Float end
        if kind=='bool' then return let_type==B.Bool end
        if kind=='pointer' then
            return let_type==B.CString or let_type==B.CPointer
                or (B.Named:isclassof(let_type) and representations[let_type.name]=='pointer')
        end
        if kind=='void' then return let_type==B.Unit end
        return false
    end
    local function add_host(name,host)
        assert(host.phase=='runtime' and (host.purity=='ordered' or host.purity=='pure'),
            'host must declare runtime phase and purity')
        assert(type(host.symbol)=='string' and host.symbol:match('^[A-Za-z_][A-Za-z0-9_]*$'),
            'host requires a symbol')
        assert(B.Signature:isclassof(host.signature) and #host.signature.results==1,
            'host requires one Let result')
        if host.c then
            for i,spelling in ipairs(host.c.params or {}) do
                local parameter=host.signature.parameters[i]
                assert(parameter,'the C prototype has more parameters than the Let signature')
                -- A mutable stage is a place, so it is a pointer whatever its pointee is.
                local ok=(parameter.capability==V.AST.Mut and c_kind(spelling)=='pointer')
                    or (parameter.capability~=V.AST.Mut and c_kind(spelling)~='unknown' and compatible(parameter.type,c_kind(spelling)))
                assert(ok,('C type %s does not describe Let parameter %d'):format(spelling,i))
            end
            if host.c.result then
                -- A Unit result discards the C value, so any C result type describes it.
                local result=host.signature.results[1]
                if result~=B.Unit then
                    local kind=c_kind(host.c.result)
                    assert(kind~='unknown' and compatible(result,kind),
                        ('C result %s does not describe the Let result'):format(host.c.result))
                end
            end
        end
        -- The boundary declares ownership and nullability, which C's type system cannot: they
        -- only mean anything for a pointer result.
        if host.ownership~=nil then
            assert(host.ownership=='owned' or host.ownership=='borrowed',
                'host ownership must be owned or borrowed')
        end
        if host.nullable~=nil then
            assert(type(host.nullable)=='boolean','host nullability must be a boolean')
        end
        if host.ownership~=nil or host.nullable~=nil then
            local result=host.signature.results[1]
            assert(result==B.CString or result==B.CPointer,
                'ownership and nullability apply to a pointer result')
        end
        -- A symbol may be declared twice with the same Let signature: a source `extern` for a
        -- libc name the embedding also registers, for instance. The first declaration wins.
        local existing=symbols[host.symbol]
        if existing then
            local same=#existing.signature.parameters==#host.signature.parameters
                and #existing.signature.results==#host.signature.results
            if same then
                for i,parameter in ipairs(existing.signature.parameters) do
                    local other=host.signature.parameters[i]
                    same=same and parameter.capability==other.capability and parameter.type:same(other.type)
                end
                for i,result in ipairs(existing.signature.results) do same=same and result:same(host.signature.results[i]) end
            end
            assert(same,'host symbol ' .. host.symbol .. ' is declared with two different signatures')
        else
            symbols[host.symbol]=host
        end
        hosts[name]=host
    end
    for name,host in pairs(options.hosts or {}) do add_host(name,host) end
    -- A namespace member is a host too, but it has no top-level name; symbol lookup still needs it.
    for _,namespace in pairs(options.dictionary or {}) do
        for name,member in pairs(namespace.members or {}) do
            if member.signature then add_host(name,member) end
        end
    end
    return setmetatable({types=types,destroy=destroy,hosts=hosts,symbols=symbols},Vocabulary)
end

function Vocabulary:type(name) return self.types[name] end
function Vocabulary:host(name) return self.hosts[name] end
function Vocabulary:destructor(name) return self.destroy[name] end

return Vocabulary
end

end)

-- let/libc.lua
module('let.libc', function(require, ...)
-- The C library the command-line host offers under the `c` namespace, so a Let program can call
-- libc with no hand-written host. Each entry states the Let signature the frontend checks, the C
-- prototype the emitter spells where a C type is not the Let type's natural mapping (§15.3), and
-- the ownership and nullability the boundary declares (spec §12.4).
--
-- `CString` is a borrowed `const char*` and `CPointer` an opaque `void*`; both are types of their
-- own rather than `Text`, and `c.string` / `c.text` are the explicit crossings.
--
-- Owned C memory is a `resource` whose C representation is a pointer (`CAlloc`), so Let owns it
-- and destroys it exactly once with `free`; there is no `c.free` to call. A foreign call that
-- mutates the bytes behind the pointer does so outside Let's invariants, which is why those calls
-- are `ordered`.
--
-- The set is deliberately small and sound at the Let type level: string, integer and byte
-- functions, no variadic form (`printf`), and no dereference or pointer arithmetic. Those need a
-- surface the specification does not define yet, and inventing one here would be a language
-- decision, not a vocabulary.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
local int=B.Parameter(B.Int,A.Read)
local cstring=B.Parameter(B.CString,A.Read)
local allocation=B.Parameter(B.Named('CAlloc'),A.Read)

local function word(symbol,purity,signature,extra)
    local descriptor={symbol=symbol,phase='runtime',purity=purity,signature=signature}
    for key,value in pairs(extra or {}) do descriptor[key]=value end
    return descriptor
end
local function ordered(symbol,signature,extra) return word(symbol,'ordered',signature,extra) end
local function pure(symbol,signature,extra) return word(symbol,'pure',signature,extra) end

return {
    -- A pointer-shaped resource: owned by Let, destroyed by `free`, never dereferenced by Let.
    resources={CAlloc={destroy='free',representation='pointer'}},
    members={
        -- The explicit crossings between a Let Text and a borrowed C string.
        string={phase='runtime',conversion='cstring'},
        text={phase='runtime',conversion='ctext'},
        -- The byte length of a Text, and a null test for a borrowed pointer.
        byte_length={phase='runtime',conversion='byte_length'},
        null={phase='runtime',conversion='null'},

        puts=ordered('puts',B.Signature(L{cstring},L{B.Int}),{c={result='int'}}),
        putchar=ordered('putchar',B.Signature(L{int},L{B.Int}),{c={params={'int'},result='int'}}),
        strlen=pure('strlen',B.Signature(L{cstring},L{B.Int}),{c={result='size_t'}}),
        strcmp=pure('strcmp',B.Signature(L{cstring,cstring},L{B.Int}),{c={result='int'}}),
        atoi=pure('atoi',B.Signature(L{cstring},L{B.Int}),{c={result='int'}}),
        llabs=pure('llabs',B.Signature(L{int},L{B.Int}),{c={params={'long long'},result='long long'}}),
        getenv=pure('getenv',B.Signature(L{cstring},L{B.CString}),
            {c={result='char *'},ownership='borrowed',nullable=true}),

        -- C memory. The allocation is the owner; `memset`/`memcpy`/`memcmp` borrow it.
        malloc=ordered('malloc',B.Signature(L{int},L{B.Named('CAlloc')}),
            {c={params={'size_t'},result='void *'}}),
        memset=ordered('memset',B.Signature(L{allocation,int,int},L{B.CPointer}),
            {c={params={'void *','int','size_t'},result='void *'}}),
        memcpy=ordered('memcpy',B.Signature(L{allocation,cstring,int},L{B.CPointer}),
            {c={params={'void *','const void *','size_t'},result='void *'}}),
        memcmp=pure('memcmp',B.Signature(L{allocation,cstring,int},L{B.Int}),
            {c={params={'const void *','const void *','size_t'},result='int'}}),
        -- A file descriptor reads into an owned allocation and writes a borrowed Text view; the
        -- count comes from `c.byte_length`, so no terminator is assumed.
        write=ordered('write',B.Signature(L{int,cstring,int},L{B.Int}),
            {c={params={'int','const void *','size_t'},result='long'}}),
        read=ordered('read',B.Signature(L{int,allocation,int},L{B.Int}),
            {c={params={'int','void *','size_t'},result='long'}}),
    },
}
end

end)

-- let/extern.lua
module('let.extern', function(require, ...)
-- Source `extern` declarations become ordinary host descriptors, so a pure Let file can call a C
-- function with no embedding registration. The declaration states the Let signature; the C
-- prototype is derived from it, and a Text argument on a type states the exact C spelling where
-- the natural mapping is not what the function wants -- `Int "size_t"`, `CString "const void *"`.
--
-- This is the producer side of spec §12.4, and it produces the very descriptor a Lua options file
-- would have written, so resolution, construction and emission see one vocabulary.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
-- `V.Lexer` is loaded after this module, so the diagnostic is looked up when it is used.
local function fail(span,message) V.Lexer.fail(span,message) end

local Extern={}

-- The C spelling a Let type maps to when the declaration does not state one.
local function natural(type_,representations)
    if type_==B.Int then return 'int64_t' end
    if type_==B.Float then return 'double' end
    if type_==B.Bool then return 'bool' end
    if type_==B.Unit then return 'void' end
    if type_==B.CString then return 'const char*' end
    if type_==B.CPointer then return 'void*' end
    if B.Named:isclassof(type_) then
        return representations[type_.name]=='pointer' and 'void*' or 'int64_t'
    end
end

-- Merge every `extern` declaration in `file` into `options.hosts`, so resolution, construction
-- and emission all see one vocabulary.
function Extern.merge(file,options)
    local hosts=options.hosts or {}
    local types={Int=B.Int,Float=B.Float,Bool=B.Bool,Unit=B.Unit,Text=B.Text,CString=B.CString,CPointer=B.CPointer}
    local representations={}
    for name,descriptor in pairs(options.resources or {}) do
        types[name]=B.Named(name)
        representations[name]=descriptor.representation or 'value'
    end
    -- A constraint is a Let type, optionally followed by a Text naming its exact C spelling.
    local function declared(constraint,span,message)
        if not constraint then return nil,nil end
        local type_=types[constraint.name]
        if not type_ then fail(span,message .. ' ' .. constraint.name) end
        local spelling
        if #constraint.arguments>0 then
            local argument=constraint.arguments[1]
            if not A.Text:isclassof(argument) then fail(span,'a C spelling must be a Text') end
            if #constraint.arguments>1 then fail(span,'a foreign type takes one C spelling') end
            spelling=argument.value
        end
        return type_,spelling
    end
    for _,item in ipairs(file.items) do
        if A.Extern:isclassof(item) then
            local parameters,cparams=L(),{}
            for i,stage in ipairs(item.parameters) do
                local type_,spelling=declared(stage.constraint,stage.span,'unknown foreign type')
                if not type_ then fail(stage.span,'foreign parameter ' .. stage.name .. ' needs a type') end
                parameters:insert(B.Parameter(type_,stage.capability))
                spelling=spelling or natural(type_,representations)
                if not spelling then fail(stage.span,'no C type for foreign parameter ' .. stage.name) end
                -- A mutable stage is a place, so it is passed by address.
                if stage.capability==A.Mut and spelling:sub(-1)~='*' then spelling=spelling .. '*' end
                cparams[i]=spelling
            end
            local result,spelling=declared(item.result,item.span,'unknown foreign type')
            result=result or B.Unit
            hosts[item.name]={symbol=item.symbol or item.name,phase='runtime',
                purity=item.pure and 'pure' or 'ordered',
                signature=B.Signature(parameters,L{result}),
                c={params=cparams,result=spelling or natural(result,representations) or 'void'}}
        end
    end
    options.hosts=hosts
    return hosts
end

return Extern
end

end)

-- let/numbering.lua
module('let.numbering', function(require, ...)
-- Numbering and dependency traversal only; not type, ownership, or effect verification.
return function(V)
    local B,L=V.Belt,V.List
    local function natural(n) return type(n)=='number' and n>=0 and n<math.huge and n==math.floor(n) end
