    for _,definition in ipairs(ctx.definitions) do
        for _,template in ipairs(definition.capture_templates or {}) do
            if #template.steps>0 or A.Body:isclassof(template.source.terminal) then
                definition.captured=true
            end
        end
    end
    return ctx
end
end


end)

-- let/program.lua
module('let.program', function(require, ...)
-- Program construction: one advancement protocol for persistent specialization and
-- transient invocation. See WORDS.md. Word values are SSA bundles (Belt.Word); a
-- statically known template's terminal becomes a belt function reached by CallFunction.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
local Build=V.Build; local Context=Build.Context
local expect,fail,gap,copy=Build.expect,Build.fail,Build.gap,Build.copy
local Packet=V.Packet
local Vocabulary=V.Vocabulary

local Builder={}; Builder.__index=Builder


function Builder.new(ast,resolved,options)
    return setmetatable({ast=ast,resolved=resolved,options=options or {},vocabulary=Vocabulary.new(options),
        layouts={},functions={false,false},entries={},templates={}},Builder)
end


-- Template layout: captures first, then items in source order, so field order equals
-- the order in which advancement produces them.
function Builder:layout(template)
    local cached=self.layouts[template.id]
    if cached then return cached end
    local items={}
    -- The contract construction needs: the stage types the body forces and the result
    -- the returns state, both computed before the body is built.
    local contract=V.Contract.template(template,self.resolved,self.vocabulary.types)
    for index,item in ipairs(template.source.items) do
        if A.Stage:isclassof(item) then
            items[index]={kind='stage',name=item.name,capability=item.capability,constraint=item.constraint,span=item.span,
                definition=self.resolved.bindings[item],inferred=contract.stages[self.resolved.bindings[item]]}
        elseif A.Prelude:isclassof(item) then
            local binding=item.binding
            items[index]={kind='prelude',name=binding.name,mutable=binding.mutable,span=binding.span,definition=self.resolved.bindings[binding]}
        else
            -- A foreign declaration produces no field; its name is a host in the vocabulary.
            items[index]={kind='extern',name=item.name,span=item.span}
        end
    end
    local captures={}
    for _,definition in ipairs(template.captures) do
        captures[#captures+1]={name=definition.name,span=definition.node.span}
    end
    local steps={}
    for _,step in ipairs(template.steps) do
        steps[#steps+1]={index=step.index,prepare=step.prepare,item=items[step.index],stage=step.stage}
    end
    cached={captures=captures,items=items,steps=steps,initial=template.initial,contract=contract}
    self.layouts[template.id]=cached
    return cached
end

-- A word bundle is immutable construction state: advancing clones it so that the
-- original receiver keeps its own stage count and field list (§5.2).
local function clone_word(word)
    local fields={} for i,field in ipairs(word.fields) do fields[i]=field end
    return {template=word.template,fields=fields,supplied=word.supplied}
end
local function copyable_fields(fields)
    for _,field in ipairs(fields) do
        if field.mutable or not field.type:copyable() then return false end
    end
    return true
end

function Builder:pack(ctx,word)
    local declared,refs=L(),L()
    for _,field in ipairs(word.fields) do
        declared:insert(B.Field(field.name,field.type,field.mutable)); refs:insert(ctx:ref(field.value))
    end
    local copy=copyable_fields(word.fields)
    local type_=B.Word(word.template.id,word.supplied,declared,copy)
    local value=ctx:emit(B.Construct(refs,copy),L{type_})
    value.word=word; value.mode='fresh'
    return value
end

-- Build one prelude binding: its initializer runs exactly once per instance, in the
-- caller's region, when advancement reaches it.
-- §5.4: a prelude reached by construction belongs to the constructed word, but one reached
-- while transiently saturating an invocation is an invocation local that the activation
-- destroys. The destination decides which, exactly like a supplied stage.
function Builder:prepare(ctx,word,layout,range,destination)
    if not range or range.last<range.first then return end
    for index=range.first,range.last do
        local item=layout.items[index]
        if item and item.kind=='prelude' then
            local value=self:value_of_binding(ctx,item.definition)
            local owned=not value.type:copyable() and not value.word
            ctx:force_bind(item.name,value,item.mutable,owned,false,false,item.span)
            word.fields[#word.fields+1]=Packet.field{name=item.name,definition=item.definition,value=value,type=value.type,
                mutable=item.mutable,owned=owned,retained=destination==B.Persistent,span=item.span}
        end
    end
end

-- The ambient destination for construction work: a word being built as the callee of an
-- invocation is constructed transiently, everything else is constructed persistently.
function Builder:destination() return self.construction_destination or B.Persistent end

function Builder:value_of_binding(ctx,definition)
    local binding=definition.node
    if #binding.value.items==0 and A.Data:isclassof(binding.value.terminal) then
        return binding.value.terminal.value:build(ctx)
    end
    return self:instantiate(ctx,definition)
end

function Builder:instantiate(ctx,definition)
    local template=definition.template
    local layout=self:layout(template)
    local word={template=template,fields={},supplied=0}
    ctx:push(); ctx:retain()
    local function captures()
        for _,capture in ipairs(layout.captures) do
            local id=ctx:find(capture.name)
            local binding=ctx.fn.bindings[id]
            local value,borrows
            if binding.address then
                -- §10.1: a non-escaping word captures an owned binding as a read borrow, and
                -- a borrow of a value is the owner's storage. The word therefore holds the
                -- owner's address, and invoking through it mutates the owner in place.
                local address=ctx.cells[id].value
                value=ctx:emit(B.BorrowPlace(ctx:ref(address),binding.lifetime=='module'),
                    L{B.Borrow(address.type.pointee,binding.lifetime=='module')},capture.span)
                value.mode='borrow'
                borrows={id}
            else
                value=ctx:read(capture.name,capture.span)
                if not value.type:copyable() then
                    gap(capture.span,'a non-Copy capture needs the owner to be a place')
                end
            end
            word.fields[#word.fields+1]=Packet.field{name=capture.name,value=value,type=value.type,
                mutable=binding.mutable,owned=false,retained=true,span=capture.span,borrows=borrows}
        end
        Packet.bind_all(ctx,word.fields)
    end
    local ok,result=pcall(function()
        captures()
        self:prepare(ctx,word,layout,layout.initial,self:destination())
        if #layout.steps==0 then
            local data=self:terminal_value(ctx,template)
            if data then return data end
        end
        return self:pack(ctx,word)
    end)
    ctx:pop()
    if not ok then error(result,0) end
    return result
end

function Builder:self_value(ctx,definition)
    local template=definition.template
    local layout=self:layout(template)
    local word={template=template,fields={},supplied=0}
    ctx:push(); ctx:retain()
    for _,capture in ipairs(layout.captures) do
        local value=ctx:read(capture.name,capture.span)
        if not value.type:copyable() then gap(capture.span,'non-Copy lexical captures (ownership/borrow capture of §10.1)') end
        word.fields[#word.fields+1]=Packet.field{name=capture.name,value=value,type=value.type,mutable=false,owned=false,retained=true,span=capture.span}
    end
    local result=self:pack(ctx,word)
    ctx:pop()
    return result
end

-- Advancing a word by one stage, whatever the value came from: an argument a call site built,
-- or a parameter a host entry was handed. There is one implementation of this, because two
-- would disagree about which stage is next and which preludes belong to it.
function Builder:advance(ctx,value,supplied,span,destination,complete)
    if not value.word then fail(span,'specialization requires a word value') end
    local word=clone_word(value.word)
    local layout=self:layout(word.template)
    local step=layout.steps[word.supplied+1]
    if not step then fail(span,'oversaturated specialization: the terminal already has every stage') end
    local item=step.item
    if supplied.word and not supplied.type:copyable() then
        gap(span,'word-valued stages')
    end
    local _,temporary=item.capability:bind_argument(supplied,destination,function(message) fail(span,message) end)
    if temporary then gap(span,'transient read borrow of owned state') end
    -- A mutable stage is a place, so its argument is the declared type's address and the
    -- constraint describes what that place contains.
    local mut=item.capability==A.Mut
    -- A mutable stage is a place, so what its constraint describes is the place's contents,
    -- not the borrow that reaches them.
    local type_=ctx:constraint(item.constraint,mut and supplied.type.pointee or supplied.type,span)
    if type_ then
        if mut then expect({type=supplied.type.pointee,origin=supplied.origin},type_,span)
        else expect(supplied,type_,span) end
    end
    if (item.capability==A.Own or item.capability==A.OwnMut) and supplied.type:borrows() then
        gap(span,'passing a word that borrows enclosing state to an ownership-taking stage')
    end
    local owned=not supplied.type:copyable() and (item.capability==A.Own or item.capability==A.OwnMut)
    -- Advancement happens in a scope holding every field the word already has. Earlier steps
    -- closed their own scopes, so without this a prelude reached at this stage could not see
    -- a prelude reached at an earlier one.
    ctx:push()
    -- A hand-off scope does not release what it bound: a call site's fields go to the callee's
    -- entry, which owns them, and a specialization's go into the word bundle. Every advancing
    -- step hands off, including a `complete` step that runs the terminal here.
    ctx:retain()
    local ok,result=pcall(function()
        Packet.bind_all(ctx,word.fields)
        -- A mutable stage is a place, exactly as it is in an entry: `build_entry` binds it as its
        -- address, so the preludes here and a host entry's terminal must see the same thing.
        local address=Packet.place(supplied.type) and supplied or false
        ctx:force_bind(item.name,supplied,owned or item.capability==A.Mut or item.capability==A.OwnMut,owned,false,address,item.span)
        word.fields[#word.fields+1]=Packet.field{name=item.name,value=supplied,type=supplied.type,
            mutable=item.capability==A.Mut or item.capability==A.OwnMut,owned=owned,
            retained=destination==B.Persistent,span=item.span,capability=item.capability}
        word.supplied=word.supplied+1
        self:prepare(ctx,word,layout,step.prepare,destination)
        if word.supplied==#layout.steps then
            -- Everything the word needs is bound right here and nowhere else: the bindings made
            -- above are discarded when this call returns, so a caller that wants to run the
            -- terminal does it now, through `complete`.
            if complete then return complete(ctx,word) end
            local data=self:terminal_value(ctx,word.template)
            if data then return data end
        end
        return self:pack(ctx,word)
    end)
    ctx:pop()
    if not ok then error(result,0) end
    return result
end

-- The value of a data terminal. A file chain with no written terminal is data too: its
-- value is the named record of its own prelude bindings, which is the module namespace.
function Builder:terminal_value(ctx,template)
    local terminal=template.source.terminal
    if terminal==nil then return self:namespace_record(ctx,template) end
    if A.Data:isclassof(terminal) then return terminal.value:build(ctx) end
    return nil
end

function Builder:namespace_record(ctx,template)
    local values,fields=L(),{}
    for _,item in ipairs(template.source.items) do
        if A.Prelude:isclassof(item) then
            local id=ctx:find(item.binding.name)
            local value=ctx.cells[id].value
            values:insert(value)
            fields[#fields+1]={name=item.binding.name,type=value.type,mutable=item.binding.mutable}
        end
    end
    return ctx:construct_record(values,fields,template.source.span)
end

function Builder:specialize(ctx,expression)
    local value=expression.word:build(ctx)
    if value.conversion then return ctx:convert(value.conversion,expression.argument,expression.span) end
    -- `import` is a construction entry: the named file's chain is constructed here, and the
    -- arguments that follow specialize it like any other word.
    if value.construction=='import' then
        local file=ctx.resolved.imports[expression]
        if not file then fail(expression.span,'unresolved import') end
        return self:instantiate(ctx,{template=ctx.resolved.chains[file]})
    end
    if not value.word then
        -- Adjacent statements juxtapose: `f() g()` is a specialization whose receiver is an
        -- invocation. That is legal shape, illegal meaning, and almost always a missing `;`.
        if A.Invoke:isclassof(expression.word) then
            fail(expression.span,'an invocation cannot be specialized: separate the two statements with ";"')
        end
        fail(expression.span,'specialization requires a word value')
    end
    -- The receiver is unchanged. A Copy receiver is copied; a fresh receiver transfers
    -- its state; an existing non-Copy receiver needs explicit independent-copy vocabulary.
    if value.mode=='borrow' then
        fail(expression.span,'specialization of an existing non-copyable word requires an explicit independent copy')
    end
    return self:supply(ctx,value,expression.argument,self:destination())
end

-- The call-site spelling of advancement: build the argument, then hand it to `advance`.
function Builder:supply(ctx,value,argument,destination)
    return self:advance(ctx,value,argument:build(ctx),argument.span,destination,nil)
end

-- The belt function for one field packet. `fields` is the packet the word already carries
-- ({type,capability,mutable,retained,owned}), which is the shape `build_entry` consumes, so
-- callers do not unpack it into parallel arrays only to have it repacked here.
function Builder:entry_function(template,fields)
    local key=Packet.key(template.id,fields)
    local existing=self.entries[key]
    if existing then return existing end
    local id=#self.functions+1
    -- Cached before the build: an entry that recurses must find itself, or it would be built twice
    -- and its callers would disagree about its signature.
    self.entries[key]=id
    self.functions[id]=false
    self.functions[id]=self:build_entry(template,fields,id)
    return id
end

-- An entry binds its parameters and runs whatever preludes lie between them. For a saturated
-- entry the call site already ran every prelude, so `supplied` is every stage and the parameters
-- are the word's fields. For a host entry the word is part way through: the parameters are its
-- captures and the items it already has, then the stages it has left, and the preludes belonging
-- to those stages run here because nobody else can run them.
function Builder:build_entry(template,fields,id)
    local layout=self:layout(template)
    local names={}
    local index=1
    for _,capture in ipairs(layout.captures) do names[index]=capture.name; index=index+1 end
    for _,item in ipairs(layout.items) do if item.kind~='extern' then names[index]=item.name; index=index+1 end end
    -- The packet's capture fields are the environment a fixing return may name, so the
    -- result type is computed here, where their types are known, not at layout time.
    local capture_types={}
    for i,definition in ipairs(template.captures) do
        capture_types[definition]=fields[i] and fields[i].type or nil
    end
    local result=V.Contract.template(template,self.resolved,self.vocabulary.types,capture_types).result
    local ctx=Context.new_function{name=(template.name or 'word') .. '_' .. id,span=template.source.span,
        vocabulary=self.vocabulary,
        builder=self,resolved=self.resolved,function_id=id,result=result}
    local fn=ctx.fn
    fn.template=template
    local records={}
    for i,field in ipairs(fields) do
        local binding,value=Packet.bind_parameter(ctx,field,names[i],template.source.span)
        records[i]={field=field,id=binding,value=value}
    end
    if template.self then ctx.self_name=template.self.name; ctx.self_definition=template.self end
    ctx.finish=function(self_,value,span)
        -- §10.1: the storage this word borrowed belongs to this activation, so the word
        -- cannot leave it.
        if value.type:borrows() then
            fail(span,'a word that borrows activation state cannot be returned from the invocation that owns it')
        end
        self_:accept_owned(value,span)
        if self_.fn.result then expect(value,self_.fn.result,span) else self_.fn.result=value.type end
        self_:pin(value)
        local updated={}
        for _,record in ipairs(records) do
            -- A place is written back by the callee itself, so it is not a result.
            if Packet.written_back(record.field) then
                updated[#updated+1]=self_:ref(self_.cells[record.id].value)
            end
        end
        self_:cleanup()
        local values=L{self_:ref(value)}; values:insertall(updated); values:insert(self_:ref(self_.effect))
        self_.block.exit=B.Return(values); self_:unpin()
    end
    for _,record in ipairs(records) do
        if Packet.mutable_state(record.field) then ctx.mutable_state=true end
    end
    -- The word's own state lives in the field scopes above; its body's locals are
    -- activation state and must be destroyed by the return, so they get their own scope
    -- rather than landing in whichever field scope happens to be current.
    local extra={}
    for _,record in ipairs(records) do
        if Packet.written_back(record.field) then extra[#extra+1]=record.field.type end
    end
    return ctx:finish_function(template.source.terminal.statements,extra)
end

function Builder:invoke(ctx,expression,tail)
    -- A callee that is constructed at this site is built transiently, because its reached
    -- preludes are invocation locals (§5.4); a named or projected word already has an owner.
    local inline=not (A.Name:isclassof(expression.word) or A.Project:isclassof(expression.word))
    local previous=self.construction_destination
    if inline then self.construction_destination=B.Transient end
    local callee=expression.word:build(ctx)
    self.construction_destination=previous
    if callee.conversion then
        if #expression.arguments~=1 then fail(expression.span,'a conversion takes exactly one argument') end
        local result=ctx:convert(callee.conversion,expression.arguments[1],expression.span)
        if tail then ctx:finish(result,expression.span); return nil end
        return result
    end
    if callee.host then
        if tail then ctx:finish(ctx:call(expression,true),expression.span) else return ctx:call(expression,false) end
        return
    end
    if not callee.word then fail(expression.span,'invocation requires a runtime word') end
    local origin=callee.origin
    -- The receiver's own bundle: transient stages are appended to a clone, and only
    -- interior mutable state may be written back into this original.
    local original=callee.word
    -- Transient saturation: each argument binds one stage, and the preludes it reaches
    -- run before the next argument is evaluated (§6.2).
    ctx:push(); ctx:retain()
    local ok,result=pcall(function()
        local value=callee
        for _,argument in ipairs(expression.arguments) do value=self:supply(ctx,value,argument,B.Transient) end
        local word=clone_word(assert(value.word,'invocation of a saturated data terminal'))
        local layout=self:layout(word.template)
        if word.supplied~=#layout.steps then fail(expression.span,'invocation must exactly saturate remaining stages') end
        -- The fields are kept as *values*, not as references. A reference is a distance from the
        -- instruction that carries it, so building one before this block emits anything else --
        -- and `cleanup` below emits destroys -- would make it mean a different producer.
        local field_values=L()
        for _,field in ipairs(word.fields) do field_values:insert(field.value) end
        local target=self:entry_function(word.template,word.fields)
        if tail then
            -- §6.5: the *caller's* own word state is not a local, so it must survive the
            -- transfer. Carrying it through the tail result needs address-taken state.
            if ctx.mutable_state then gap(expression.span,'tail invocation from a word with mutable state') end
            -- §6.5: a tail transfer retires this activation, so a place this activation owns
            -- cannot be passed. Only a borrow of module storage would survive, and the type
            -- does not distinguish that, so any borrow is conservative here.
            for _,field in ipairs(word.fields) do
                if field.type:borrows() then
                    fail(expression.span,'tail invocation borrow does not outlive caller cleanup')
                end
            end
            local callee=self.functions[target]
            if callee and #callee.signature.results>2 then
                local borrowed=false
                for _,field in ipairs(word.fields) do
                    if B.Address:isclassof(field.type) then borrowed=true end
                end
                if borrowed then
                    gap(expression.span,'tail invocation of a captured word: its state must be written back, which a tail transfer cannot do')
                end
                gap(expression.span,'tail invocation of a word whose state belongs to the retiring activation')
            end
            -- A function whose only exit is a tail call takes its result type from the callee.
            if not ctx.fn.result then
                if callee and callee.signature then
                    ctx.fn.result=callee.signature.results[1]
                else
                    -- A self tail transfer: the result is the word's own, which the contract
                    -- states; nothing else fixes it before the transfer.
                    gap(expression.span,'result type of a word whose only exit is a self tail call')
                end
            end
            ctx:cleanup()
            ctx.block.exit=B.TailCall(target,ctx:ref(ctx.effect),ctx:refs(field_values))
            return nil
        end
        local callee=self.functions[target]
        local result_type
        if callee and callee.signature then
            result_type=callee.signature.results[1]
        elseif target==ctx.function_id then
            -- A direct self call returns whatever this word returns, which the contract states.
            result_type=ctx.fn.result
            if not result_type then
                gap(expression.span,'the result type of a recursive call must be fixed by another return in the same word')
            end
        else
            gap(expression.span,'the result type of a recursive call must be fixed by another return in the same word')
        end
        local types=L{result_type}
        for i,field in ipairs(word.fields) do if Packet.written_back(field) then types:insert(field.type) end end
        types:insert(B.Effect)
        local results={ctx:emit(B.CallFunction(target,ctx:ref(ctx.effect),ctx:refs(field_values)),types,expression.span)}
        ctx.effect=results[#results]
        -- §3.4: an invocation is a specialization atom. A Word-typed result names its template and
        -- supplied count, and its fields are the members of what the callee returned, so the word
        -- identity survives the call. Copy only: an owned word crossing a call boundary needs the
        -- ownership rules for that stated first, and says so rather than being guessed at.
        if B.Word:isclassof(result_type) then
            if not result_type.is_copy then
                gap(expression.span,'a returned word with owned state needs ownership vocabulary')
            end
            local template
            for _,candidate in ipairs(self.resolved.templates) do
                if candidate.id==result_type.template then template=candidate end
            end
            if not template then gap(expression.span,'unresolved word template ' .. tostring(result_type.template)) end
            local fields={}
            for i,field in ipairs(result_type.fields) do
                fields[i]={name=field.name,type=field.type,mutable=field.mutable,owned=false,retained=false,
                    span=expression.span,
                    value=ctx:emit(B.LoadField(ctx:ref(results[1]),i-1),L{field.type},expression.span)}
            end
            local rebuilt=copy(results[1])
            rebuilt.word={template=template,fields=fields,supplied=result_type.supplied}
            rebuilt.mode='fresh'
            results[1]=rebuilt
        end
        -- Only interior mutable state is written back, and only into the receiver's
        -- existing bundle. A transient specialization of a partial word must not
        -- replace that binding with a saturated one.
        local updated=original
        local changed=false
        local at=2
        for i,field in ipairs(word.fields) do
            if Packet.written_back(field) and i<=#original.fields then
                if not changed then
                    updated=clone_word(original); changed=true
                end
                local replaced={} for key,value in pairs(updated.fields[i]) do replaced[key]=value end
                replaced.value=results[at]; updated.fields[i]=replaced; at=at+1
            end
        end
        if changed then
            -- Interior state must be written back to its owner. A projected word member has
            -- no writable place of its own yet, so its state update would be silently lost.
            if not origin then gap(expression.span,'invoking a projected word member with mutable state') end
            local packed=self:pack(ctx,updated)
            local binding=ctx.fn.bindings[origin]
            if binding.address then
                -- The owner's record is a place: write the updated record back into it, which
                -- is what lets a captured word share its state with the capture's owner.
                ctx:ordered(B.Store(ctx:ref(ctx.effect),ctx:ref(ctx.cells[origin].value),ctx:ref(packed)),nil,expression.span)
            else
                ctx.cells[origin]={value=packed,initialized=true,alive=binding.owned,moved={}}
            end
        end
        local result=results[1]; result.mode=result.type:copyable() and 'copy' or 'fresh'; result.origin=origin
        return result
    end)
    ctx:pop()
    if not ok then error(result,0) end
    return result
end

-- §15.1: the module initializer constructs the namespace, and the module's owned state
-- lives until unload. Both are returned: the namespace is what the host projects, and the
-- state is the owner, destroyed once by the unload function in reverse successful-
-- construction order. One owner avoids the namespace and the state each destroying the same
-- value; a written terminal that moves an owned prelude into the namespace only changes what
-- the host can *see*, not who destroys it.
function Builder:build_module()
    local file=self.ast.file
    local ctx=Context.new_function{name='__module_init',span=file.span,state=nil,
        vocabulary=self.vocabulary,
        builder=self,resolved=self.resolved,lifetime='module'}
    local fn=ctx.fn
    local order,ids,fields=L(),L(),L()
    for index,item in ipairs(file.items) do
        if A.Stage:isclassof(item) then item:bind_parameter(ctx,index,self.options)
        elseif A.Extern:isclassof(item) then
            -- A foreign declaration is not a module binding: its name is a host in the vocabulary.
        else
            A.Local(item.binding,item.binding.span):build(ctx)
            local id=ctx:find(item.binding.name)
            -- The binding id is recorded, not its value handle: the terminal body may split
            -- the CFG, and a prelude's current value is then the block parameter that carried
            -- it, which only the context at the return point knows. The state keeps the
            -- binding's construction position, which is what destruction order needs.
            ids:insert(id)
            order:insert(item.binding.name)
            fields:insert({name=item.binding.name,type=ctx.cells[id].value.type,mutable=item.binding.mutable})
        end
    end
    -- The current value of each prelude binding, asked where the state record is built.
    local function state_values(target)
        local values=L()
        for _,id in ipairs(ids) do values:insert(target.cells[id].value) end
        return values
    end
    -- Module bindings live until module unload, not until initialization returns, so a
    -- borrow of module storage outlives any value that holds it.
    ctx.scopes[1].retained=true
    self.module_order=order
    local namespace
    if file.terminal==nil then
        -- The common case: the namespace is exactly the prelude record, so it is its own
        -- state and there is nothing to duplicate.
        local state=ctx:construct_record(state_values(ctx),fields,fn.span)
        self.module_exports=self:export_map(fields)
        -- A field that is a word is a host entry point: the namespace holds it, and the host
        -- invokes it by supplying its remaining stages. Recorded here, where the preludes are
        -- still values rather than references.
        self.exports={}
        for i,field in ipairs(fields) do
            if B.Word:isclassof(field.type) then
                self.exports[#self.exports+1]={name=field.name,value=ctx.cells[ids[i]].value,span=fn.span}
            end
        end
        ctx:finish_pair(state,state,fn.span)
    elseif A.Data:isclassof(file.terminal) then
        ctx.module_preludes={}
        for _,item in ipairs(file.items) do
            if A.Prelude:isclassof(item) then ctx.module_preludes[ctx:find(item.binding.name)]=true end
        end
        namespace=file.terminal.value:build(ctx)
        ctx.module_preludes=nil
        local state=ctx:construct_record(state_values(ctx),fields,fn.span)
        self.module_exports=self:export_map(namespace.type)
        ctx:finish_pair(namespace,state,fn.span)
    else
        -- A written do terminal is the initialization body; its return is the namespace.
        -- The module's preludes are still the module's own state, so the body's return is
        -- paired with the state record rather than being returned as the state, and the
        -- same pairing is installed for every return inside the body.
        ctx.module_preludes={}
        for _,item in ipairs(file.items) do
            if A.Prelude:isclassof(item) then ctx.module_preludes[ctx:find(item.binding.name)]=true end
        end
        fn.module_pending=function(target,namespace,span)
            -- The restriction applies to the namespace the body produced; the state record
            -- is where untouched preludes belong, exactly as for a written terminal.
            target.module_preludes=nil
            local state=target:construct_record(state_values(target),fields,span)
            target:finish_pair(namespace,state,span)
        end
        -- The body's own locals are activation state, not module state: they live in their
        -- own scope so that the return destroys them, while the preludes stay retained.
        ctx:push()
        ctx:statements(file.terminal.statements)
        if not ctx.block.exit then
            fn.module_pending(ctx,ctx:emit(B.UnitLiteral,L{B.Unit},fn.span),fn.span)
        end
        fn.module_pending=nil
        ctx.module_preludes=nil
        if not ctx.block.exit then ctx:pop() end
        self.module_exports=self:export_map(ctx.fn.result)
    end
    return self:module_function(ctx,'__module_init')
end

-- A host projects exports by index, so record the mapping instead of making it guess.
function Builder:export_map(source)
    local exports={}
    if B.Aggregate:isclassof(source) then
        for i,field in ipairs(source.fields) do if field.name then exports[field.name]=i-1 end end
    elseif type(source)=='table' then
        for i,field in ipairs(source) do if field.name then exports[field.name]=i-1 end end
    end
    return exports
end

function Builder:module_function(ctx,label)
    local fn=ctx.fn
    local blocks=ctx:blocks()
    local results=L{fn.result,fn.state}
    results:insert(B.Effect)
    return B.Function(label,B.Signature(blocks[1].parameters,results),blocks)
end

-- §15.1: destroy the module's owned state in reverse successful-construction order. The
-- state record's members are already in construction order, so destroying it is the whole
-- function; a record destroys its own contents in reverse (§8.5).
function Builder:build_unload(state_type)
    local ctx=Context.new_function{name='__module_unload',span=self.ast.file.span,
        vocabulary=self.vocabulary,
        builder=self,resolved=self.resolved}
    local fn=ctx.fn
    ctx:destroy(ctx:parameter(state_type),fn.span)
    ctx:finish(ctx:emit(B.UnitLiteral,L{B.Unit},fn.span),fn.span)
    local blocks=ctx:blocks()
    return B.Function(fn.name,B.Signature(blocks[1].parameters,L{fn.result,B.Effect}),blocks)
end


-- The host's way into an exported word: its first arguments are the word's own fields -- the
-- construction trace so far, which the host reads from the namespace -- and the stages it still
-- needs follow. Advancing uses the same protocol a call site uses, so nothing here decides which
-- stage is next or which preludes belong to it: `advance` already knows, because it does it for
-- call sites every day.
function Builder:host_entry(name,value,span)
    local word=value.word
    if not word then return nil,'not a word value' end
    local template=word.template
    local layout=self:layout(template)
    -- Decide before allocating anything: a stage whose type only an argument can determine means
    -- there is no signature to publish, and leaving a hole in the function list would be worse
    -- than having no entry.
    local resolve=Context.new_function{name='resolve',span=span,vocabulary=self.vocabulary,
        resolved=self.resolved}
    local stages,items={},{}
    for i=word.supplied+1,#layout.steps do
        local item=layout.steps[i].item
        -- A declared type is the contract; otherwise the terminal body may force one. A
        -- `Copy` stage whose forced type is not copyable cannot be published.
        local type_=resolve:constraint_type(item.constraint) or item.inferred
        if type_ and item.constraint and item.constraint.name=='Copy' and not type_:copyable() then
            type_=nil
        end
        if not type_ then
            return nil,'stage ' .. tostring(item.name) .. ' has no type without an argument'
        end
        stages[i]=type_; items[i]=item
    end
    local id=#self.functions+1
    -- A host entry is named apart from the word it stands for: the word's own name is what a host
    -- embedding already projects, and a benchmark driver calls `let_<case>`, so the entry must not
    -- claim that spelling. `statistics` publishes the name the host should call.
    local ctx=Context.new_function{name=name .. '_host',span=span,
        vocabulary=self.vocabulary,
        builder=self,resolved=self.resolved,function_id=id}
    local fn=ctx.fn
    fn.template=template
    self.functions[id]=false
    -- §4.2 the defining word is visible in its own terminal body.
    if template.self then ctx.self_name=template.self.name; ctx.self_definition=template.self end
    -- The word's own fields are parameters like any other: they are the construction trace, and a
    -- mutable one is a place, so its binding is its address.
    -- The trace is rebuilt from the host's parameters, not from the word's own field values.
    -- `advance` re-binds the trace by name at every stage, so a trace still holding the values the
    -- *initializer* produced would shadow these parameters with values from another context.
    local trace={}
    for _,field in ipairs(word.fields) do
        local _,parameter,owned=Packet.bind_parameter(ctx,field,field.name,span)
        trace[#trace+1]=Packet.field{name=field.name,value=parameter,type=field.type,mutable=field.mutable,
            owned=owned,retained=field.retained,span=span,capability=field.capability}
    end
    -- Every parameter exists before the first instruction: a parameter created once emission has
    -- started takes a position after an instruction and collides with it.
    local parameters={}
    for i=word.supplied+1,#layout.steps do
        parameters[i]=Packet.stage_parameter(ctx,items[i].capability,stages[i],items[i].span)
    end
    -- What a saturated word means for a host: the fields the entry was handed, plus the ones its
    -- stages produced, are exactly the parameters of the word's own entry. Running that entry is
    -- what a call site does, so the host entry is a wrapper and one template emits one body.
    local function complete(c,saturated)
        local data=self:terminal_value(c,template)
        if data then
            -- No entry is built to own the fields, so the host entry destroys them here.
            for i=#saturated.fields,1,-1 do
                local field=saturated.fields[i]
                if field.owned then c:destroy(field.value,field.span or span) end
            end
            return c:finish(data,span)
        end
        local field_values=L()
        for _,field in ipairs(saturated.fields) do field_values:insert(field.value) end
        local target=self:entry_function(saturated.template,saturated.fields)
        local callee=assert(self.functions[target],'a host entry calls an entry this build just made')
        local types=L()
        for i=1,#callee.signature.results do types:insert(callee.signature.results[i]) end
        local results={c:emit(B.CallFunction(target,c:ref(c.effect),c:refs(field_values)),types,span)}
        c.effect=results[#results]
        return c:finish(results[1],span)
    end
    local current={type=value.type,word={template=template,fields=trace,supplied=word.supplied}}
    for i=word.supplied+1,#layout.steps do
        current=self:advance(ctx,current,parameters[i],items[i].span,B.Transient,
            i==#layout.steps and complete or nil)
    end
    -- A word that is already saturated has no stages left to advance, so its terminal has not run
    -- yet: the fields bound above are the whole of its state.
    if word.supplied>=#layout.steps then complete(ctx,{template=template,fields=trace,supplied=word.supplied}) end
    local blocks=ctx:blocks('unfinished host entry')
    self.functions[id]=B.Function(fn.name,B.Signature(blocks[1].parameters,L{fn.result,B.Effect}),blocks)
    return {name=name,id=id,bundle=#word.fields,stages=#layout.steps-word.supplied}
end

function Builder:build()
    local module=self:build_module()
    self.functions[1]=module
    self.functions[2]=self:build_unload(module.signature.results[2])
    -- After the module interface, so ids 1 and 2 stay what the host already expects.
    self.host_entries={}
    -- One host entry per exported word: the interface the embedding calls (§15.1). A word that
    -- cannot offer an ABI is skipped with its reason recorded (see the loop below).
    if self.options.host_entries~=false then
        self.host_entry_skips={}
        for _,export in ipairs(self.exports or {}) do
            -- An entry is an interface the word may not be able to offer: a body that invokes a
            -- captured word reaches fields belonging to the initializer's context, which is a gap
            -- in this compiler rather than a fault in the program. The word is still legal, so the
            -- entry is skipped and the reason recorded.
            local before=#self.functions
            local ok,entry,reason=pcall(self.host_entry,self,export.name,export.value,export.span)
            if ok and entry then self.host_entries[#self.host_entries+1]=entry
            else
                -- A failed entry may already have interned the functions it built on the way down,
                -- so both the function slots and the cache entries naming them are dropped.
                for i=before+1,#self.functions do self.functions[i]=nil end
                for key,id in pairs(self.entries) do if id>before then self.entries[key]=nil end end
                self.host_entry_skips[export.name]= ok and reason or tostring(entry):gsub('^.*: ','')
            end
        end
    end
    local functions=L()
    for _,fn in ipairs(self.functions) do functions:insert(fn) end
    local templates=L()
    for _,template in ipairs(self.resolved.templates) do
        templates:insert(B.Template(tostring(template.id),#template.steps,#template.captures,template.source.span))
    end
    return B.Program(self.options.name or '__program',templates,functions):verify_flow(self.vocabulary.symbols)
end

function A.Program:build(options)
    options=options or {}
    -- A source `extern` becomes an ordinary host descriptor, so it reaches resolution,
    -- construction and emission as one vocabulary.
    V.Extern.merge(self.file,options)
    local resolved=self:resolve(options)
    local builder=Builder.new(self,resolved,options)
    local program=builder:build()
    builder.program=program
    return program,builder
end

function A.Word:build(ctx)
    local builder=ctx.builder; if not builder then gap(self.span,'word values require a program builder') end
    local template=ctx.resolved.chains[self.chain]
    if not template then gap(self.span,'unresolved word construction') end
    return builder:instantiate(ctx,{template=template})
end
end

end)

-- let/op.lua
module('let.op', function(require, ...)
-- One definition of each pure operation, shared by the abstract evaluator and the concrete test
-- oracle, so folding cannot disagree with execution (DEMAND.md §3). The exact scalar semantics
-- live in `let/scalar`; this table says which one an operator means.
return function(V)
local A=V.AST
local scalar=require('let.scalar')

local Op={}

-- Binary operators over known values. `Divide` here is non-trapping Float division; an Int
-- division is a `CheckedBinary` and uses `Op.checked`, which traps.
Op.binary={
    [A.Add]=scalar.add, [A.Subtract]=scalar.subtract, [A.Multiply]=scalar.multiply,
    [A.Divide]=scalar.fdivide,
    [A.Equal]=scalar.equal, [A.NotEqual]=scalar.not_equal,
    [A.Less]=scalar.less, [A.LessEqual]=scalar.less_equal,
    [A.Greater]=scalar.greater, [A.GreaterEqual]=scalar.greater_equal,
    [A.And]=function(a,b) return a and b end, [A.Or]=function(a,b) return a or b end,
}

Op.unary={
    [A.Negate]=scalar.negate, [A.Not]=function(a) return not a end,
    [A.ToFloat]=scalar.to_float, [A.ToInt]=scalar.to_int,
    [A.TextSize]=scalar.text_size,
    -- `IsNull` is not here: a pointer is not a Let value, so it never folds.
}

-- Operations that can trap, used when the divisor is not known non-zero.
Op.checked={[A.Divide]=scalar.divide, [A.Remainder]=scalar.remainder}

return Op
end

end)

-- let/known.lua
module('let.known', function(require, ...)
-- Abstract evaluation over a verified belt: the computing half of demand.
--
-- An answer is `Known(v)` -- exact, and derived only from the rules in DEMAND.md §6 -- or
-- `Runtime(T)`. Ordered operations are never folded, because their result types include
-- Effect. That makes the purity gate structural rather than conventional.
--
-- This machine shares §13.2 scalar semantics with the concrete interpreter through
-- `let.scalar`, so folding cannot disagree with execution.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
local scalar=require('let.scalar')
local Op=V.Op   -- one shared definition of each pure operation, with the concrete oracle

local Known={}

-- Answers -------------------------------------------------------------------------

function Known.runtime(type_) return {runtime=true,type=type_} end
function Known.value(type_,value) return {type=type_,value=value} end
function Known.bundle(type_,fields) return Known.value(type_,{fields=fields}) end
-- A record with a known shape and a known value in *some* members. It is not one constant,
-- so it is never substituted or pruned, but reading a known member of it is, and a member
-- both branches agree on stays known through a join.
function Known.partial(type_,fields) return {type=type_,value={fields=fields},partial=true} end
-- `is_known` means "one constant": what substitution, pruning and arithmetic require.
function Known.is_known(answer) return answer~=nil and answer.runtime~=true and answer.partial~=true end
function Known.is_runtime(answer) return answer==nil or answer.runtime==true end
-- `answered` also admits a partial record: there is an answer, just not one value.
function Known.answered(answer) return answer~=nil and answer.runtime~=true end

local function is_bundle(type_) return B.Word:isclassof(type_) or B.Aggregate:isclassof(type_) end

function Known.same(a,b)
    if a==nil or b==nil then return false end
    if Known.is_runtime(a) or Known.is_runtime(b) then
        return Known.is_runtime(a) and Known.is_runtime(b) and a.type:same(b.type)
    end
    if not a.type:same(b.type) then return false end
    if is_bundle(a.type) then
        local fields=a.type.fields
        for i=1,#fields do if not Known.same(a.value.fields[i],b.value.fields[i]) then return false end end
        return true
    end
    return scalar.equal(a.value,b.value)
end

function Known.join(a,b)
    if a==nil then return b end
    if b==nil then return a end
    if Known.same(a,b) then return a end
    -- Two records that are not one constant may still agree member by member, which is what
    -- a join is for: a member every path agrees on stays known.
    if Known.answered(a) and Known.answered(b) and is_bundle(a.type) and a.type:same(b.type) then
        local fields,partial={},false
        for i=1,#a.type.fields do
            local field=Known.join(a.value.fields[i],b.value.fields[i])
            fields[i]=field
            if not Known.is_known(field) then partial=true end
        end
        return partial and Known.partial(a.type,fields) or Known.bundle(a.type,fields)
    end
    return Known.runtime(a.type)
end

-- A canonical, injective-enough text form, used to intern summaries.
function Known.key(answer)
    if Known.is_runtime(answer) then return '?' .. tostring(answer.type) end
    if is_bundle(answer.type) then
        local parts={}
        for _,field in ipairs(answer.value.fields) do parts[#parts+1]=Known.key(field) end
        return '{' .. table.concat(parts,',') .. '}'
    end
    if answer.type==B.Int then local hi,lo=scalar.limbs(answer.value); return ('i%08x%08x'):format(hi,lo) end
    if answer.type==B.Bool then return answer.value and 'b1' or 'b0' end
    if answer.type==B.Unit then return 'u' end
    if answer.type==B.Text then return 't' .. #answer.value .. ':' .. answer.value end
    if answer.type==B.Float then return ('f%a'):format(answer.value) end
    return '?' .. tostring(answer.type)
end

-- A run holds everything shared between a root function and its callees.
local Evaluator
local Run={}; Run.__index=Run
function Run.new(program,options)
    return setmetatable({program=program,hosts=(options or {}).hosts or {},
        instances={},budget=(options or {}).summary_budget or 256},Run)
end

-- The unit of demand is an *instance*: a belt function together with the answers of the entry
-- packet it is called with. Its key is exactly that pair, which is also what a call site has
-- when it decides what to call, so one cache serves both the fold question and emission's
-- question of which C function a call names.
function Run:key(target,seeded)
    local parts={tostring(target)}
    if seeded then for _,answer in ipairs(seeded) do parts[#parts+1]=Known.key(answer) end end
    return table.concat(parts,',')
end

function Run:instance(target,seeded)
    local key=self:key(target,seeded)
    local cached=self.instances[key]
    if cached~=nil then return cached or nil end
    if self.budget<=0 then return nil end
    -- Marked in progress: a cycle must not re-enter the same instance.
    self.instances[key]=false; self.budget=self.budget-1
    local evaluator=Evaluator.new(self,self.program.functions[target],{parameters=seeded})
    evaluator:analyze()
    self.instances[key]=evaluator
    return evaluator
end

-- A summary is a *view* of an instance, derived once: `answered` when every value result has
-- an answer, `foldable` when every one of them is a constant and the callee demanded no
-- ordered work. The two are different questions -- answers replace the uses of a call that
-- still happens, foldability removes the call -- and an instance that produced no results at
-- all has answered nothing, which the loop must not read as success.
local function summarize(program,target,evaluator)
    if evaluator.summary~=nil then return evaluator.summary or nil end
    local signature=program.functions[target].signature
    local answered,foldable=#evaluator.results==#signature.results,not evaluator.residual
    for i,answer in ipairs(evaluator.results) do
        if signature.results[i]~=B.Effect then
            if not Known.answered(answer) then answered=false end
            if not Known.is_known(answer) then foldable=false end
        end
    end
    evaluator.summary=answered and {results=evaluator.results,foldable=foldable} or false
    return evaluator.summary or nil
end

function Run:summary(target,seeded)
    local evaluator=self:instance(target,seeded)
    if not evaluator then return nil end
    return summarize(self.program,target,evaluator)
end

-- Evaluator ------------------------------------------------------------------------

Evaluator={}; Evaluator.__index=Evaluator

function Evaluator.new(run,belt,options)
    local self=setmetatable({run=run,program=run.program,hosts=run.hosts,belt=belt,options=options or {},
        answers={},params={},decision={},widened={},residual=false},Evaluator)
    self:reset()
    return self
end

-- Seeded parameters are how a call site asks about a concrete packet; anything not seeded
-- is a generic runtime input.
function Evaluator:reset()
    self.answers,self.params,self.decision,self.widened,self.residual={},{},{},{},false
    self.changed=false
    local seeded=self.options.parameters
    if seeded then
        local entry={}
        for i,answer in ipairs(seeded) do entry[i]=answer end
        self.params[1]=entry
    end
end

-- Concrete-abstract execution: follow one iteration at a time while every control decision
-- remains decidable. This is what lets a loop with a known trip count fold away entirely,
-- which widening alone cannot do because it deliberately forgets the induction variable.
-- It gives up on anything it cannot enumerate: an undecidable branch, a repeated instance,
-- demanded ordered work, or the step budget.
function Evaluator:enumerate()
    local budget=self.options.unroll_limit or 32
    local visited,steps,returns={},0,nil
    local function key_of(block_id,packet)
        local parts={block_id}
        for _,answer in ipairs(packet) do parts[#parts+1]=Known.key(answer) end
        return table.concat(parts,'|')
    end
    local function visit(block_id,packet)
        if steps>=budget then return false end
        local key=key_of(block_id,packet)
        if visited[key] then return false end
        visited[key]=true; steps=steps+1
        local block=self.belt.blocks[block_id]
        self.params[block_id]=packet
        local demanded=self.needed[block_id]
        local recorded={}
        self.answers[block_id]=recorded
        for index,instruction in ipairs(block.instructions) do
            local position=#block.parameters+index-1
            if demanded and demanded[position] then
                recorded[position]=self:instruction(block,block_id,index,instruction)
                -- Ordered work has to be emitted, so it cannot be executed here.
                if self.residual then return false end
            end
        end
        local position=#block.parameters+#block.instructions
        local exit=block.exit
        local function packet_of(edge)
            local packet={}
            for i,ref in ipairs(edge.arguments) do packet[i]=self:resolve(block,block_id,position,ref) end
            return packet
        end
        if B.Return:isclassof(exit) then
            returns=packet_of({arguments=exit.values})
            return true
        elseif B.Branch:isclassof(exit) then
            local condition=self:resolve(block,block_id,position,exit.condition)
            if not Known.is_known(condition) then return false end
            return visit((condition.value and exit.yes or exit.no).target,packet_of(condition.value and exit.yes or exit.no))
        elseif B.Jump:isclassof(exit) then
            return visit(exit.edge.target,packet_of(exit.edge))
        end
        return false
    end
    local entry={}
    for i,parameter in ipairs(self.belt.blocks[1].parameters) do entry[i]=self:parameter(1,i) end
    if not visit(1,entry) then return false end
    -- Fold only if nothing observable remains and every value result is exact.
    local types=self.belt.signature.results
    for i,type_ in ipairs(types) do
        if type_~=B.Effect and not Known.is_known(returns[i]) then return false end
    end
    self.results=returns
    return true
end

-- Blocks participating in a cycle. Without widening, a known value must not travel
-- around a backedge, so their parameters stay Runtime.
function Known.cyclic_blocks(belt)
    local on_cycle={}
    local function reaches(from,to,seen)
        if from==to then return true end
        if seen[from] then return false end
        seen[from]=true
        for _,edge in ipairs(belt.blocks[from].exit:edges()) do
            if reaches(edge.target,to,seen) then return true end
        end
        return false
    end
    for id,block in ipairs(belt.blocks) do
        for _,edge in ipairs(block.exit:edges()) do
            if edge.target<=id and reaches(edge.target,id,{}) then on_cycle[id]=true; on_cycle[edge.target]=true end
        end
    end
    return on_cycle
end

function Evaluator:parameter(block_id,index)
    local entry=self.params[block_id]
    if entry and entry[index] then return entry[index] end
    return Known.runtime(self.belt.blocks[block_id].parameters[index].type)
end

function Evaluator:param(block_id,index) return self:parameter(block_id,index) end

-- Whether a CallFunction was removed is recorded on its own answers, so it lives and dies
-- with them. A side table would outlive them -- an answer table is rebuilt every pass -- and
-- emission would then remove a call whose result another expression still refers to.
function Evaluator:call_was_folded(block_id,position)
    local recorded=self.answers[block_id]
    local slot=recorded and recorded[position]
    return slot~=nil and slot.folded==true
end

function Evaluator:answer(block_id,position,output)
    local block=self.answers[block_id]
    local answers=block and block[position]
    return answers and answers[output+1]
end

function Evaluator:resolve(block,block_id,position,ref)
    local producer=position-1-ref.distance
    if producer<#block.parameters then return self:parameter(block_id,producer+1) end
    local answer=self:answer(block_id,producer,ref.output)
    if answer then return answer end
    local result=block.instructions[producer-#block.parameters+1].results[ref.output+1]
    return Known.runtime(result)
end


-- Ordered work was demanded and could not be folded, so no caller may fold this away.
function Evaluator:schedule(operation)
    self.residual=true
    self.scheduled=self.scheduled or {}
    self.scheduled[#self.scheduled+1]=tostring(operation)
end

function Evaluator:instruction(block,block_id,index,instruction)
    local position=#block.parameters+index-1
    local operation=instruction.operation
    local results={}
    local function put(output,answer) results[output+1]=answer end
    local function runtime_all()
        for i=1,#instruction.results do put(i-1,Known.runtime(instruction.results[i])) end
    end
    local function inputs(refs)
        local out={} for i,ref in ipairs(refs) do out[i]=self:resolve(block,block_id,position,ref) end
        return out
    end
    local function all_known(list)
        for _,answer in ipairs(list) do if not Known.is_known(answer) then return false end end
        return true
    end

    if B.IntegerLiteral:isclassof(operation) then
        put(0,Known.value(B.Int,scalar.integer(operation.spelling,error)))
    elseif B.FloatLiteral:isclassof(operation) then
        put(0,Known.value(B.Float,scalar.float(operation.spelling,error)))
    elseif B.BooleanLiteral:isclassof(operation) then
        put(0,Known.value(B.Bool,operation.value))
    elseif B.UnitLiteral:isclassof(operation) then
        put(0,Known.value(B.Unit,scalar.unit))
    elseif B.TextLiteral:isclassof(operation) then
        put(0,Known.value(B.Text,operation.value))
    elseif B.Unary:isclassof(operation) then
        local operand=inputs{operation.operand}[1]
        -- A C string is not a Let value: a pointer has no known representation, and measuring a
        -- C string is run-time work, so these stay residual.
        if operation.operator==A.ToCString or operation.operator==A.ToText or operation.operator==A.IsNull then
            put(0,Known.runtime(instruction.results[1]))
        elseif Known.is_known(operand) then
            local value=Op.unary[operation.operator](operand.value)
            put(0,Known.value(instruction.results[1],value))
        else put(0,Known.runtime(instruction.results[1])) end
    elseif B.Binary:isclassof(operation) then
        local arguments=inputs{operation.left,operation.right}
        if all_known(arguments) then
            local value=Op.binary[operation.operator](arguments[1].value,arguments[2].value)
            put(0,Known.value(instruction.results[1],value))
        else put(0,Known.runtime(instruction.results[1])) end
    elseif B.CheckedBinary:isclassof(operation) then
        local arguments=inputs{operation.left,operation.right}
        -- §16.2: omit a check only when failure is proved impossible. A known non-zero
        -- divisor proves it; anything else keeps the residual checked operation.
        if all_known(arguments) and arguments[2].value~=0 then
            local rule=Op.checked[operation.operator]
            put(0,Known.value(B.Int,rule(arguments[1].value,arguments[2].value)))
        else
            put(0,Known.runtime(B.Int)); self:schedule(operation)
        end
        put(1,Known.runtime(B.Effect))
    elseif B.FieldAddress:isclassof(operation) then
        put(0,Known.runtime(instruction.results[1]))
    elseif B.BorrowPlace:isclassof(operation) then
        put(0,Known.runtime(instruction.results[1]))
    elseif B.Construct:isclassof(operation) then
        -- Every member has an answer, because a run-time input answers `runtime`. The record
        -- is one constant only when no member is run-time; otherwise it is a partial record,
        -- which is what lets its known members still be read.
        local arguments=inputs(operation.fields)
        local fields,partial={},false
        for i,answer in ipairs(arguments) do
            fields[i]=answer
            if not Known.is_known(answer) then partial=true end
        end
        put(0,partial and Known.partial(instruction.results[1],fields) or Known.bundle(instruction.results[1],fields))
    elseif B.LoadField:isclassof(operation) then
        -- Reading a member answers with that member's own answer, constant or not.
        local answer=inputs{operation.record}[1]
        if Known.answered(answer) and answer.value.fields[operation.field+1] then
            put(0,answer.value.fields[operation.field+1])
        else put(0,Known.runtime(instruction.results[1])) end
    elseif B.StoreField:isclassof(operation) then
        local answer=inputs{operation.record}[1]
        if Known.answered(answer) then
            local fields,partial={},false
            for i,field in ipairs(answer.value.fields) do
                fields[i]=field
                if not Known.is_known(field) then partial=true end
            end
            local stored=inputs{operation.value}[1]
            fields[operation.field+1]=stored
            if not Known.is_known(stored) then partial=true end
            if partial then put(0,Known.partial(instruction.results[1],fields))
            else put(0,Known.bundle(instruction.results[1],fields)) end
        else put(0,Known.runtime(instruction.results[1])) end
    elseif B.CallFunction:isclassof(operation) then
        -- Every argument has an answer, a run-time one included, and that is exactly the
        -- packet the callee's evaluator would seed anyway. Asking for the summary is
        -- therefore unconditional; what bounds the work is the budget and the in-progress
        -- mark, not a guess about which calls can fold.
        local arguments=inputs(operation.arguments)
        local seeded={Known.runtime(B.Effect)}
        for i,answer in ipairs(arguments) do seeded[i+1]=answer end
        local summary=self.run:summary(operation.target,seeded)
        if summary then
            for i,answer in ipairs(summary.results) do put(i-1,answer) end
            -- A precise summary whose results are not all constants still leaves the call in
            -- place, and its order with it. The mark goes on these answers, not beside them.
            if summary.foldable then results.folded=true else self:schedule(operation) end
        else runtime_all(); self:schedule(operation) end
    elseif B.HostCall:isclassof(operation) or B.PureHostCall:isclassof(operation) then
        runtime_all()
        if B.HostCall:isclassof(operation) then self:schedule(operation) end
    elseif B.Move:isclassof(operation) then
        -- Ownership is static, so a move is an identity on the value.
        put(0,self:resolve(block,block_id,position,operation.value))
        put(1,Known.runtime(B.Effect))
    elseif B.Destroy:isclassof(operation) then
        put(0,Known.runtime(B.Effect)); self:schedule(operation)
    else
        -- Load, Store, Allocate and anything not yet modeled: memory identity is
        -- observable, so the operation stays and there is no known result.
        runtime_all(); self:schedule(operation)
    end
    return results
end

-- A packet field supplied by an edge. A predecessor's own field may have no value yet
-- during the first pass; that is reported as nil so the join can stay optimistic, and
-- `verify_packets` is what makes the optimism sound.
function Evaluator:supplied(source,source_id,ref)
    local position=#source.parameters+#source.instructions
    local producer=position-1-ref.distance
    if producer<#source.parameters then
        local entry=self.params[source_id]
        return entry and entry[producer+1]
    end
    return self:answer(source_id,producer,ref.output)
end

-- The join over every live incoming edge. `optimistic` skips a contribution that does not
-- exist yet; otherwise a missing contribution is Runtime.
function Evaluator:incoming(block_id,optimistic)
    local belt=self.belt
    local joined,seen={},0
    for source_id,source in ipairs(belt.blocks) do
        if self.live_blocks[source_id] then
            local allowed=self.decision[source_id]
            for _,edge in ipairs(source.exit:edges()) do
                if edge.target==block_id and (allowed==nil or allowed==edge) then
                    seen=seen+1
                    for i,ref in ipairs(edge.arguments) do
                        local answer=self:supplied(source,source_id,ref)
                        if answer then joined[i]=Known.join(joined[i],answer)
                        elseif not optimistic then joined[i]=Known.join(joined[i],Known.runtime(self.belt.blocks[block_id].parameters[i].type)) end
                    end
                end
            end
        end
    end
    return joined,seen
end

function Evaluator:block(block_id)
    local belt=self.belt
    local block=belt.blocks[block_id]
    if block_id~=1 then
        local joined,seen=self:incoming(block_id,true)
        local previous=self.params[block_id] or {}
        local widened=self.widened[block_id]
        local next_={}
        for i,parameter in ipairs(block.parameters) do
            -- A widened packet stays widened: the iteration must move only toward Runtime,
            -- otherwise a later pass could reduce it again and oscillate.
            if widened and widened[i] then next_[i]=Known.runtime(parameter.type)
            else next_[i]=(seen>0 and joined[i]) or Known.runtime(parameter.type) end
            if not Known.same(previous[i],next_[i]) then self.changed=true end
        end
        self.params[block_id]=next_
    end
    local demanded=self.needed[block_id]
    local previous=self.answers[block_id]
    -- The table is published before it is filled so a reference to an earlier
    -- producer in the same block sees this pass's answer, not the previous pass's.
    local recorded={}
    self.answers[block_id]=recorded
    for index,instruction in ipairs(block.instructions) do
        local position=#block.parameters+index-1
        if demanded and demanded[position] then
            local answers=self:instruction(block,block_id,index,instruction)
            recorded[position]=answers
            for output,answer in ipairs(answers) do
                local was=previous and previous[position] and previous[position][output]
                if not Known.same(was,answer) then self.changed=true end
            end
        end
    end
    local exit=block.exit
    if B.Branch:isclassof(exit) then
        local condition=self:resolve(block,block_id,#block.parameters+#block.instructions,exit.condition)
        local decision=Known.is_known(condition) and (condition.value and exit.yes or exit.no) or nil
        if decision~=self.decision[block_id] then self.decision[block_id]=decision; self.changed=true end
    end
end

-- Blocks reachable through edges that were not falsified.
function Evaluator:live()
    local live,work={[1]=true},{1}
    while #work>0 do
        local id=table.remove(work)
        local allowed=self.decision[id]
        for _,edge in ipairs(self.belt.blocks[id].exit:edges()) do
            if (allowed==nil or allowed==edge) and not live[edge.target] then
                live[edge.target]=true; work[#work+1]=edge.target
            end
        end
    end
    return live
end

-- A stored packet is sound only if it equals the join of what the edges really supply.
-- An optimistic pass can guess a loop-carried value; this pass recomputes the true join
-- from the guessed answers and widens any packet that does not agree. Widening only ever
-- moves toward Runtime, so the outer loop terminates.
function Evaluator:verify_packets()
    local belt=self.belt
    local changed=false
    for block_id=2,#belt.blocks do
        if self.live_blocks[block_id] then
            local block=belt.blocks[block_id]
            local joined=self:incoming(block_id,false)
            for i,parameter in ipairs(block.parameters) do
                local stored=self:parameter(block_id,i)
                local actual=joined[i] or Known.runtime(parameter.type)
                if Known.is_known(stored) and not Known.same(stored,actual) then
                    self.params[block_id][i]=actual
                    self.widened[block_id]=self.widened[block_id] or {}
                    self.widened[block_id][i]=true
                    changed=true
                end
            end
        end
    end
    return changed
end

-- Widen every packet of a block in a cycle. The fallback when the fixed point needs more
-- iterations than the budget allows: it is always sound, and it terminates.
function Evaluator:widen_cycles()
    for block_id in pairs(Known.cyclic_blocks(self.belt)) do
        local block=self.belt.blocks[block_id]
        local next_={}
        self.widened[block_id]=self.widened[block_id] or {}
        for i,parameter in ipairs(block.parameters) do
            next_[i]=Known.runtime(parameter.type)
            self.widened[block_id][i]=true
        end
        self.params[block_id]=next_
    end
end

function Evaluator:fixpoint(limit)
    for _=1,limit do
        self.changed=false
        for block_id=1,#self.belt.blocks do
            if self.live_blocks[block_id] then self:block(block_id) end
        end
        self.live_blocks=self:live()
        if not self.changed then return true end
    end
    return false
end

function Evaluator:analyze()
    local belt=self.belt
    self.needed=self.options.demands or belt:demands()
    if self:enumerate() then
        -- Everything the function does is decided and nothing observable remains. That makes
        -- the body a constant only if every value it returns *is* one: a decided body can
        -- still return a run-time parameter, and then it has to be emitted.
        local constant=true
        for i,answer in ipairs(self.results or {}) do
            if self.belt.signature.results[i]~=B.Effect and not Known.is_known(answer) then constant=false end
        end
        if constant then
            self.folded=true
            self.live_blocks={}
            return self
        end
    end
    self:reset()
    local limit=self.options.iteration_limit or 16
    self.live_blocks=self:live()
    local verified=false
    for _=1,limit do
        if not self:fixpoint(limit) then
            -- The optimistic pass did not settle; fall back to generic loop packets.
            self:widen_cycles()
            self:fixpoint(limit)
        end
        self.live_blocks=self:live()
        if not self:verify_packets() then verified=true; break end
        -- A widened packet changes the answers, so settle again before re-verifying.
        self:fixpoint(limit)
        self.live_blocks=self:live()
    end
    if not verified then self:widen_cycles(); self:fixpoint(limit); self.live_blocks=self:live() end
    local results
    for block_id in pairs(self.live_blocks) do
        local exit=belt.blocks[block_id].exit
        if B.Return:isclassof(exit) then
            local position=#belt.blocks[block_id].parameters+#belt.blocks[block_id].instructions
            local packet={}
            for i,ref in ipairs(exit.values) do packet[i]=self:resolve(belt.blocks[block_id],block_id,position,ref) end
            if results then
                for i,answer in ipairs(packet) do results[i]=Known.join(results[i],answer) end
            else results=packet end
        end
    end
    self.results=results or {}
    return self
end

Known.Evaluator=Evaluator

-- Analyze one belt function generically (all incoming parameters Runtime).
function Known.analyze(program,function_id,options)
    local run=options and options.run or Run.new(program,options)
    local evaluator=Evaluator.new(run,program.functions[function_id],options or {})
    evaluator:analyze()
    return evaluator,run
end

function Known.run(program,options) return Run.new(program,options) end

return Known
end

end)

-- let/file.lua
module('let.file', function(require, ...)
-- A default import resolver for hosts that do not supply their own.
--
-- §15.2 fixes only the *semantics* of an import: the named file's chain is constructed at
-- the import site. Where a path is looked up, which extension is assumed, and whether
-- anything is cached are embedding decisions, so they live here beside the compiler rather
-- than in the language. A host with its own layout should pass its own resolver instead.
return function(options)
    options=options or {}
    local suffix=options.suffix==nil and '.let' or options.suffix
    local roots=options.roots or {}
    return function(path,from)
        local directory=from and from:match('^(.*)/') or '.'
        local candidates={path}
        if suffix~='' and path:sub(-#suffix)~=suffix then candidates[#candidates+1]=path..suffix end
        -- Relative to the importing file first, then the configured roots, then as given.
        local bases={directory}
        for _,root in ipairs(roots) do bases[#bases+1]=root end
        bases[#bases+1]=''
        for _,base in ipairs(bases) do
            for _,candidate in ipairs(candidates) do
                local full=(base=='' and candidate) or (base .. '/' .. candidate)
                local file=io.open(full,'r')
                if file then
                    local text=file:read('*a'); file:close()
                    return {text=text,file=full}
                end
            end
        end
        return nil
    end
end

end)

-- let/print.lua
module('let.print', function(require, ...)
-- Render the C output vocabulary. This prints C; it decides no Let semantics.
return function(V)
local C=V.C
local function uint64_text(hi,lo) return ('0x%08x%08xULL'):format(hi,lo) end
-- Small magnitudes print in decimal so the emitted C stays readable; anything else keeps
-- the exact hexadecimal form, which also avoids ever writing INT64_MIN as a negated literal.
local function integer(hi,lo)
    if hi==0 and lo<2147483648 then return ('INT64_C(%d)'):format(lo) end
    if hi==4294967295 and lo>=2147483648 then return ('(-INT64_C(%d))'):format(4294967296-lo) end
    return '((int64_t)' .. uint64_text(hi,lo) .. ')'
end
local function quoted(text)
    local parts={'"'}
    for i=1,#text do
        local byte=text:byte(i)
        parts[#parts+1]=('\\%03o'):format(byte)
    end
    parts[#parts+1]='"'
    return table.concat(parts)
end
local function indent(level) return string.rep('    ',level) end

function C.Type:print() error('missing C type printer',0) end
function C.Void:print() return 'void' end
function C.Bool:print() return 'bool' end
function C.I64:print() return 'int64_t' end
function C.U64:print() return 'uint64_t' end
function C.F64:print() return 'double' end
function C.U8:print() return 'uint8_t' end
function C.Size:print() return 'size_t' end
function C.Pointer:print() return self.pointee:print() .. '*' end
function C.Named:print() return self.name end

function C.Expr:print() error('missing C expression printer',0) end
function C.Integer:print() return integer(self.hi,self.lo) end
function C.Float:print()
    if self.value~=self.value then return 'NAN' end
    if self.value==math.huge then return 'INFINITY' end
    if self.value==-math.huge then return '(-INFINITY)' end
    return string.format('%a',self.value)
end
function C.Boolean:print() return self.value and 'true' or 'false' end
function C.String:print() return quoted(self.value) end
function C.Name:print() return self.name end
function C.Unary:print() return '(' .. self.operator .. self.operand:print() .. ')' end
function C.Binary:print() return '(' .. self.left:print() .. ' ' .. self.operator .. ' ' .. self.right:print() .. ')' end
function C.Cast:print() return '((' .. self.type:print() .. ')' .. self.value:print() .. ')' end
function C.Call:print()
    local parts={} for _,argument in ipairs(self.arguments) do parts[#parts+1]=argument:print() end
    return self.callee:print() .. '(' .. table.concat(parts,', ') .. ')'
end
function C.Field:print() return '(' .. self.base:print() .. ').' .. self.name end
function C.Index:print() return '(' .. self.base:print() .. ')[' .. self.index:print() .. ']' end
function C.Compound:print()
    local parts={} for _,field in ipairs(self.fields) do parts[#parts+1]=field:print() end
    return '((' .. self.type:print() .. '){' .. table.concat(parts,', ') .. '})'
end

-- Renders one statement. `lines` accumulates output; `level` is the indent depth.
local function statement(node,level,lines)
    local pad=indent(level)
    if C.Declare:isclassof(node) then
        local text=node.type:print() .. ' ' .. node.name
        if node.initial then text=text .. ' = ' .. node.initial:print() end
        lines[#lines+1]=pad .. text .. ';'
    elseif C.Assign:isclassof(node) then
        lines[#lines+1]=pad .. node.place:print() .. ' = ' .. node.value:print() .. ';'
    elseif C.Evaluate:isclassof(node) then
        lines[#lines+1]=pad .. node.value:print() .. ';'
    elseif C.Block:isclassof(node) then
        lines[#lines+1]=pad .. '{'
        for _,child in ipairs(node.statements) do statement(child,level+1,lines) end
        lines[#lines+1]=pad .. '}'
    elseif C.If:isclassof(node) then
        lines[#lines+1]=pad .. 'if (' .. node.condition:print() .. ')'
        statement(node.yes,level,lines)
        if node.no then lines[#lines+1]=pad .. 'else'; statement(node.no,level,lines) end
    elseif C.While:isclassof(node) then
        lines[#lines+1]=pad .. 'while (' .. node.condition:print() .. ')'
        statement(node.body,level,lines)
    elseif C.Label:isclassof(node) then
        lines[#lines+1]=node.name .. ':;'
    elseif C.Goto:isclassof(node) then
        lines[#lines+1]=pad .. 'goto ' .. node.name .. ';'
    elseif C.Return:isclassof(node) then
        lines[#lines+1]=node.value and (pad .. 'return ' .. node.value:print() .. ';') or (pad .. 'return;')
    else error('missing C statement printer',0) end
end

-- An empty list must print as (void): a bare () is an unprototyped declaration in C,
-- which conflicts with a later definition that passes promoted arguments.
local function parameters(list)
    if #list==0 then return 'void' end
    local parts={} for _,parameter in ipairs(list) do parts[#parts+1]=parameter.type:print() .. ' ' .. parameter.name end
    return table.concat(parts,', ')
end

local function declaration(node,lines)
    if C.Struct:isclassof(node) then
        lines[#lines+1]='struct ' .. node.name .. ' {'
        for _,field in ipairs(node.fields) do lines[#lines+1]='    ' .. field.type:print() .. ' ' .. field.name .. ';' end
        lines[#lines+1]='};'
    elseif C.Function:isclassof(node) then
        local prefix=node.external and 'extern ' or 'static '
        local head=prefix .. node.result:print() .. ' ' .. node.name .. '(' .. parameters(node.parameters) .. ')'
        if not node.body then lines[#lines+1]=head .. ';'; return end
        lines[#lines+1]=head .. ' {'
        statement(node.body,1,lines)
        lines[#lines+1]='}'
    elseif C.Global:isclassof(node) then
        lines[#lines+1]='static ' .. node.type:print() .. ' ' .. node.name .. ';'
    elseif C.Raw:isclassof(node) then
        lines[#lines+1]=node.code
    else error('missing C declaration printer',0) end
end

-- A null body is a forward declaration; `external` marks a host-provided symbol.
function C.Unit:print()
    local lines={}
    for _,include in ipairs(self.includes) do lines[#lines+1]='#include <' .. include .. '>' end
    if #lines>0 then lines[#lines+1]='' end
    for _,node in ipairs(self.declarations) do declaration(node,lines); lines[#lines+1]='' end
    return table.concat(lines,'\n')
end
V.print=function(unit) return unit:print() end
end

end)

-- let/emit.lua
module('let.emit', function(require, ...)
-- Belt to C. The belt is already the semantic program, so this pass only chooses
-- representations and prints them. It is not a second semantic IR and never decides
-- evaluation order: statements follow the belt's ordered effect chain.
return function(V)
local A,B,C,L=V.AST,V.Belt,V.C,V.List
local literal=require('let.literal')
local Known=V.Known
local scalar=V.scalar

local Emitter={}; Emitter.__index=Emitter


function Emitter.new(options)
    return setmetatable({options=options or {},structs={},struct_names={},results={},result_names={},
        names={},helpers={},used_hosts={},used_destroys={},destroy_pointer={},text=false,stdbool=true,trap=false,
        instances={},pending={},generic={},serial={},self_tail={}},Emitter)
end

-- A host may state the C prototype it calls, because that ABI is an embedding detail (§15.3).
-- The Let types already map to C (`CString` is `const char*`, the scalars are themselves), so
-- only an integer of a different width needs a cast.
local function compact(name) return (name:gsub('%s','')) end
local c_integer={}
for _,name in ipairs{'char','signedchar','unsignedchar','short','unsignedshort','int','unsigned',
    'long','unsignedlong','longlong','unsignedlonglong','size_t','ssize_t','ptrdiff_t','intptr_t',
    'uintptr_t','int8_t','uint8_t','int16_t','uint16_t','int32_t','uint32_t','int64_t','uint64_t'} do
    c_integer[name]=true
end
local function c_integer_type(name) return c_integer[compact(name)]==true end

function Emitter:host_arguments(host,arguments)
    local converted=L()
    for i,value in ipairs(arguments) do
        local spelling=host.c and host.c.params and host.c.params[i]
        if spelling and c_integer_type(spelling) then
            converted:insert(C.Cast(C.Named(spelling),value))
        else
            converted:insert(value)
        end
    end
    return converted
end

function Emitter:host_result(host,call)
    local spelling=host.c and host.c.result
    -- A Unit result discards the value, so there is nothing to convert.
    if spelling and host.signature.results[1]~=B.Unit and c_integer_type(spelling) then
        return C.Cast(C.I64,call)
    end
    return call
end

function Emitter:error(message) error('C emission: ' .. message,0) end

function Emitter:register_struct(fields)
    local key='s'
    for _,field in ipairs(fields) do key=key .. '|' .. field:key() end
    local existing=self.struct_names[key]
    if existing then return "struct " .. existing end
    -- Nested aggregate fields must be declared first, so the name is chosen only
    -- after this struct's own fields have registered theirs.
    local declarations=L()
    -- Field names are zero-based to match belt member indices.
    for i,field in ipairs(fields) do declarations:insert(C.Parameter(self:ctype(field.type),'f' .. (i-1))) end
    local name='let_val_' .. (#self.structs+1)
    self.struct_names[key]=name
    self.structs[#self.structs+1]=C.Struct(name,declarations)
    return 'struct ' .. name
end

function Emitter:ctype(type_)
    if type_==B.Int then return C.I64 end
    if type_==B.Bool then return C.Bool end
    if type_==B.Unit then return C.U8 end
    if type_==B.Effect then return C.U64 end
    if type_==B.Float then self.math=true; return C.F64 end
    if type_==B.Text then self.text=true; return C.Named('struct let_text') end
    if type_==B.CString then return C.Pointer(C.Named('const char')) end
    if type_==B.CPointer then return C.Pointer(C.Named('void')) end
    if B.Named:isclassof(type_) then
        -- A resource is an integer handle by default, or a C pointer when it declares one.
        local descriptor=self.options.resources and self.options.resources[type_.name]
        if descriptor and descriptor.representation=='pointer' then return C.Pointer(C.Named('void')) end
        return C.I64
    end
    if B.Address:isclassof(type_) or B.Borrow:isclassof(type_) then return C.Pointer(self:ctype(type_.pointee)) end
    if B.Aggregate:isclassof(type_) or B.Word:isclassof(type_) then
        -- A record with no fields carries no information, and an empty struct is not ISO C.
        if #type_.fields==0 then return C.U8 end
        return C.Named(self:register_struct(type_.fields))
    end
    self:error('no representation for ' .. tostring(type_))
end

-- Effect tokens are ordering evidence for the frontend and have no C representation: the
-- belt's statement order already carries the order. Dropping them removes the effect
-- parameter, the effect field of every result, and every effect update.
function Emitter:value_types(types)
    local values={}
    for _,type_ in ipairs(types) do if type_~=B.Effect then values[#values+1]=type_ end end
    return values
end

-- A function returning no value is `void`; one returning a single value returns that type
-- directly. Only a genuine multiple result needs a struct.
function Emitter:return_shape(types)
    local values=self:value_types(types)
    if #values==0 then return C.Void,0 end
    if #values==1 then return self:ctype(values[1]),1 end
    local key='r'
    for _,type_ in ipairs(values) do key=key .. '|' .. type_:key() end
    local existing=self.result_names[key]
    if existing then return C.Named('struct ' .. existing),#values end
    local name='let_ret_' .. (#self.results+1)
    self.result_names[key]=name
    local declarations=L()
    for i,type_ in ipairs(values) do declarations:insert(C.Parameter(self:ctype(type_),'r' .. (i-1))) end
    self.results[#self.results+1]=C.Struct(name,declarations)
    return C.Named('struct ' .. name),#values
end

-- `values` are the materialized results only; the effect has already been dropped.
function Emitter:return_value(type_,values)
    if type_==C.Void then return nil end
    if #values==1 then return values[1] end
    return C.Compound(type_,values)
end

-- Negation is applied in 64-bit two's-complement form here rather than in C, where
-- negating INT64_MIN would be undefined and the magnitude may exceed a Lua number.
function Emitter:literal(spelling)
    local negative=spelling:sub(1,1)=='-'
    local _,_,hi,lo=literal.integer(negative and spelling:sub(2) or spelling,negative,function(m) self:error(m) end)
    if not negative or (hi==0 and lo==0) then return C.Integer(hi,lo) end
    local borrowed=lo==0 and 0 or 1
    return C.Integer((4294967296-hi-borrowed)%4294967296, lo==0 and 0 or 4294967296-lo)
end

function Emitter:param(belt_id,index) return 'p' .. belt_id .. '_' .. index end
function Emitter:value(belt_id,index,output) return 'v' .. belt_id .. '_' .. index .. '_' .. output end

-- Answers come from the abstract evaluator. A known answer is inlined at every use and its
-- producer is never written out, so folding removes work rather than hiding it. Which answers
-- exist, and where a producer's answer lives, is `disposition`'s business, not the emitter's:
-- reaching for an answer directly is how one rule became several.

function Emitter:constant(answer)
    local type_=answer.type
    if type_==B.Int then local hi,lo=scalar.limbs(answer.value); return C.Integer(hi,lo) end
    if type_==B.Float then self.math=true; return C.Float(answer.value) end
    if type_==B.Bool then return C.Boolean(answer.value) end
    if type_==B.Unit then return C.Integer(0,0) end
    if type_==B.Text then return C.Compound(self:ctype(B.Text),L{C.String(answer.value),C.Integer(0,#answer.value)}) end
    if B.Word:isclassof(type_) or B.Aggregate:isclassof(type_) then
        if #answer.value.fields==0 then return C.Integer(0,0) end
        local fields=L()
        for _,field in ipairs(answer.value.fields) do fields:insert(self:constant(field)) end
        return C.Compound(self:ctype(type_),fields)
    end
    self:error('no C constant for ' .. tostring(type_))
end

-- Resolve a belt reference to the C expression holding that output.
function Emitter:ref(block,block_id,position,ref)
    -- Unit has exactly one value. It is materialized by whatever produced it -- an ordered call
    -- emits a statement rather than a variable -- so a use of it is the constant, never a name.
    local _,ref_type=block:resolve(position,ref)
    if ref_type==B.Unit then return C.Integer(0,0) end
    local producer=position-1-ref.distance
    local fate,answer=self:disposition(self.current_instance.analysis,self.current,block_id,producer,ref.output)
    if fate=='constant' then return self:constant(answer) end
    if producer<#block.parameters then return C.Name(self:param(block_id,producer)) end
    return C.Name(self:value(block_id,producer-#block.parameters+1,ref.output))
end

function Emitter:arglist(block,block_id,position,refs)
    local out=L() for _,ref in ipairs(refs) do out:insert(self:ref(block,block_id,position,ref)) end
    return out
end

local symbolic={[A.Add]='+',[A.Subtract]='-',[A.Multiply]='*',[A.Divide]='/',[A.Less]='<',[A.LessEqual]='<=',
    [A.Greater]='>',[A.GreaterEqual]='>=',[A.Equal]='==',[A.NotEqual]='!=',[A.And]='&&',[A.Or]='||'}
local arithmetic={[A.Add]={'add','LET_ADD'}, [A.Subtract]={'sub','LET_SUB'}, [A.Multiply]={'mul','LET_MUL'}}


local function statement_list(list)
    local declarations=L(); for _,entry in ipairs(list) do declarations:insert(entry) end; return declarations
end

-- Emits one instruction. Returns a statement list; output variables are named by
-- (block, instruction index, output) so relative references stay resolvable.
function Emitter:instruction(block,block_id,index,instruction)
    local position=#block.parameters+index-1
    local operation=instruction.operation
    local out={}
    -- One question, asked of the same place the body filter and every reference asks.
    local function known(output)
        return self:disposition(self.current_instance.analysis,self.current,block_id,position,output)=='constant'
    end
    local function declare(output,type_,expr)
        if type_==B.Effect then return false end
        if known(output) then return false end
        out[#out+1]=C.Declare(self:ctype(type_),self:value(block_id,index,output),expr)
        return true
    end
    if B.IntegerLiteral:isclassof(operation) then
        declare(0,B.Int,self:literal(operation.spelling))
    elseif B.FloatLiteral:isclassof(operation) then
        self.math=true
        declare(0,B.Float,C.Float(scalar.float(operation.spelling,error)))
    elseif B.BooleanLiteral:isclassof(operation) then
        declare(0,B.Bool,C.Boolean(operation.value))
    elseif B.UnitLiteral:isclassof(operation) then
        declare(0,B.Unit,C.Integer(0,0))
    elseif B.TextLiteral:isclassof(operation) then
        self.text=true
        declare(0,B.Text,C.Compound(self:ctype(B.Text),L{C.String(operation.value),C.Integer(0,#operation.value)}))
    elseif B.Unary:isclassof(operation) then
        local operand=self:arglist(block,block_id,position,{operation.operand})[1]
        if operation.operator==A.Not then declare(0,B.Bool,C.Unary('!',operand))
        elseif operation.operator==A.ToFloat then declare(0,B.Float,C.Cast(self:ctype(B.Float),operand))
        elseif operation.operator==A.ToInt then
            if declare(0,B.Int,C.Call(C.Name('let_to_int'),L{operand})) then self.helpers.to_int=true end
        elseif operation.operator==A.ToCString then
            declare(0,B.CString,C.Field(operand,'data'))
        elseif operation.operator==A.ToText then
            self.text=true; self.helpers.text_from_c=true
            declare(0,B.Text,C.Call(C.Name('let_text_from_c'),L{operand}))
        elseif operation.operator==A.TextSize then
            declare(0,B.Int,C.Cast(C.I64,C.Field(operand,'size')))
        elseif operation.operator==A.IsNull then
            declare(0,B.Bool,C.Binary('==',operand,C.Integer(0,0)))
        elseif instruction.results[1]==B.Float then declare(0,B.Float,C.Unary('-',operand))
        elseif declare(0,B.Int,C.Call(C.Name('LET_NEG'),L{operand})) then self.helpers.neg=true end
    elseif B.Binary:isclassof(operation) then
        local arguments=self:arglist(block,block_id,position,{operation.left,operation.right})
        local _,type_=block:resolve(position,operation.left)
        if known(0) then return statement_list(out) end
        if type_==B.Float then
            self.math=true
            declare(0,instruction.results[1],C.Binary(symbolic[operation.operator],arguments[1],arguments[2]))
        elseif operation.operator==A.Equal or operation.operator==A.NotEqual then
            -- `symbolic` already spells the operator: `==` or `!=` for a scalar, and the one Text
            -- macro *is* equality, so only that case has anything left to negate. Negating the
            -- scalar case too made `!=` compare equal and vice versa.
            local call,negated
            if type_==B.Text then
                self.helpers.text_eq=true
                call=C.Call(C.Name('LET_TEXT_EQ'),L{arguments[1],arguments[2]})
                negated=operation.operator==A.NotEqual
            else
                call=C.Binary(symbolic[operation.operator],arguments[1],arguments[2])
                negated=false
            end
            declare(0,B.Bool,negated and C.Unary('!',call) or call)
        elseif arithmetic[operation.operator] then
            local helper=arithmetic[operation.operator]
            self.helpers[helper[1]]=true
            declare(0,B.Int,C.Call(C.Name(helper[2]),L{arguments[1],arguments[2]}))
        else
            declare(0,instruction.results[1],C.Binary(symbolic[operation.operator],arguments[1],arguments[2]))
        end
    elseif B.CheckedBinary:isclassof(operation) then
        local arguments=self:arglist(block,block_id,position,{operation.left,operation.right})
        local helper=operation.operator==A.Divide and 'let_div' or 'let_rem'
        if not known(0) then self.helpers[operation.operator==A.Divide and 'div' or 'rem']=true end
        local effect=self:ref(block,block_id,position,operation.effect)
        -- §16.2: a non-zero known divisor proves the check cannot fail, so it is omitted.
        if declare(0,B.Int,C.Call(C.Name(helper),L{arguments[1],arguments[2]})) then
            self.trap=true
            declare(1,B.Effect,C.Binary('+',effect,C.Integer(0,1)))
        else declare(1,B.Effect,effect) end
    elseif B.FieldAddress:isclassof(operation) then
        -- A field's address: the same storage, reached one level in.
        local place=self:ref(block,block_id,position,operation.place)
        declare(0,instruction.results[1],C.Unary('&',C.Field(C.Unary('*',place),'f' .. operation.field)))
    elseif B.BorrowPlace:isclassof(operation) then
        -- A borrow is the same storage, so nothing is emitted for the operation itself; only
        -- the type changed, and that is a frontend matter.
        declare(0,instruction.results[1],self:ref(block,block_id,position,operation.address))
    elseif B.Construct:isclassof(operation) then
        if #operation.fields==0 then declare(0,instruction.results[1],C.Integer(0,0))
        else declare(0,instruction.results[1],C.Compound(self:ctype(instruction.results[1]),self:arglist(block,block_id,position,operation.fields))) end
    elseif B.LoadField:isclassof(operation) then
        local base=self:ref(block,block_id,position,operation.record)
        declare(0,instruction.results[1],C.Field(base,'f' .. operation.field))
    elseif B.StoreField:isclassof(operation) then
        local word=self:ref(block,block_id,position,operation.record)
        local type_=instruction.results[1]
        local fields=L()
        for i=0,#type_:record()-1 do
            if i==operation.field then fields:insert(self:ref(block,block_id,position,operation.value))
            else fields:insert(C.Field(word,'f' .. i)) end
        end
        declare(0,type_,C.Compound(self:ctype(type_),fields))
    elseif B.Allocate:isclassof(operation) then
        -- A cell is storage whose address is taken. Storage is chosen after the contract is
        -- known (WORDS.md §9): a value that must be observable as a place becomes memory, and
        -- an address that never escapes can still be promoted by the C compiler.
        local address=instruction.results[1]
        local cell=self:value(block_id,index,'c')
        if self.current_id==1 then
            -- Module state lives until unload, so a module cell needs storage that outlives
            -- the initializer's frame: a captured word holds this address.
            self.statics[#self.statics+1]=C.Global(self:ctype(address.pointee),cell)
            out[#out+1]=C.Assign(C.Name(cell),self:ref(block,block_id,position,operation.initial))
        else
            out[#out+1]=C.Declare(self:ctype(address.pointee),cell,self:ref(block,block_id,position,operation.initial))
        end
        declare(0,address,C.Unary('&',C.Name(cell)))
        declare(1,B.Effect,C.Binary('+',self:ref(block,block_id,position,operation.effect),C.Integer(0,1)))
    elseif B.Load:isclassof(operation) then
        declare(0,instruction.results[1],C.Unary('*',self:ref(block,block_id,position,operation.address)))
        declare(1,B.Effect,C.Binary('+',self:ref(block,block_id,position,operation.effect),C.Integer(0,1)))
    elseif B.Store:isclassof(operation) then
        out[#out+1]=C.Assign(C.Unary('*',self:ref(block,block_id,position,operation.address)),
            self:ref(block,block_id,position,operation.value))
        declare(0,B.Effect,C.Binary('+',self:ref(block,block_id,position,operation.effect),C.Integer(0,1)))
    elseif B.CallFunction:isclassof(operation) then
        -- The callee's effect parameter is not part of its C signature.
        local callee=self:callee_instance(operation.target,block,block_id,position,operation.arguments)
        local call=C.Call(C.Name(callee.name),
            self:call_arguments(callee,block,block_id,position,operation.arguments))
        local type_,count=self:return_shape(self.functions[operation.target].signature.results)
        -- A call the evaluator answered but kept still happens, even when every result it
        -- returns is a constant: the answer replaces the *uses*, not the call. Only the
        -- declaration is dropped, never the evaluation.
        if count==0 then
            out[#out+1]=C.Evaluate(call)
        elseif count==1 then
            if known(0) then out[#out+1]=C.Evaluate(call) else declare(0,instruction.results[1],call) end
        else
            local temporary=self:value(block_id,index,'t')
            out[#out+1]=C.Declare(type_,temporary,call)
            local output=0
            for _,result in ipairs(instruction.results) do
                if result~=B.Effect then
                    if not known(output) then declare(output,result,C.Field(C.Name(temporary),'r' .. output)) end
                    output=output+1
                end
            end
        end
    elseif B.HostCall:isclassof(operation) or B.PureHostCall:isclassof(operation) then
        local host=self.hosts[operation.symbol] or self:error('missing host contract for ' .. operation.symbol)
        self.used_hosts[host.symbol]=host
        local arguments=self:host_arguments(host,self:arglist(block,block_id,position,operation.arguments))
        local call=self:host_result(host,C.Call(C.Name(operation.symbol),statement_list(arguments)))
        local pure=B.PureHostCall:isclassof(operation)
        if instruction.results[1]==B.Unit then out[#out+1]=C.Evaluate(call)
        else out[#out+1]=C.Declare(self:ctype(instruction.results[1]),self:value(block_id,index,0),call) end
        if not pure then
            local effect=self:ref(block,block_id,position,operation.effect)
            declare(#instruction.results-1,B.Effect,C.Binary('+',effect,C.Integer(0,1)))
        end
    elseif B.Move:isclassof(operation) then
        local value=self:ref(block,block_id,position,operation.value)
        if declare(0,instruction.results[1],value) then
            declare(1,B.Effect,C.Binary('+',self:ref(block,block_id,position,operation.effect),C.Integer(0,1)))
        else declare(1,B.Effect,self:ref(block,block_id,position,operation.effect)) end
    elseif B.Destroy:isclassof(operation) then
        self.used_destroys[operation.destructor]=true
        local value=self:ref(block,block_id,position,operation.value)
        out[#out+1]=C.Evaluate(C.Call(C.Name(operation.destructor),L{value}))
        declare(0,B.Effect,C.Binary('+',self:ref(block,block_id,position,operation.effect),C.Integer(0,1)))
    else
        self:error('no representation for ' .. tostring(operation))
    end
    return statement_list(out)
end

-- Instances ----------------------------------------------------------------------------
--
-- The unit of emission is an *instance*: a belt function together with the answers of the
-- entry packet it is called with, which is the same key `Run` caches an analysis under. One
-- function per belt id was the special case of that where nothing is known about the packet,
-- so the generic instance is not a fallback bolted on beside specialization -- it is the
-- instance with no information, and it is what the module interface itself uses.

-- The instance a function has knowing nothing about its entry packet.
function Emitter:generic_instance(id)
    local existing=self.generic[id]
    if existing then return existing end
    local instance=self:add_instance(id,self.run:instance(id,nil),self.run:key(id,nil),true)
    self.generic[id]=instance
    return instance
end

function Emitter:add_instance(id,analysis,key,generic)
    local serial=(self.serial[id] or 0)+1
    self.serial[id]=serial
    local instance={id=id,belt=self.functions[id],analysis=analysis,key=key,generic=generic,
        name=generic and self:function_name(id) or (self:function_name(id) .. '_' .. serial)}
    self.instances[key]=instance
    self.pending[#self.pending+1]=instance
    return instance
end

-- A self tail transfer changes the entry packet in place, so no packet of such a function is
-- fixed and every call to it uses the generic instance.
function Emitter:self_tail_recursive(id)
    local known=self.self_tail[id]
    if known~=nil then return known end
    local found=false
    for _,block in ipairs(self.functions[id].blocks) do
        if B.TailCall:isclassof(block.exit) and block.exit.target==id then found=true end
    end
    self.self_tail[id]=found
    return found
end

-- The instance a call names. A packet with no constant is the generic instance; one with a
-- constant gets an instance of its own, unless the budget is spent or the instance is already
-- being analysed, in which case the generic one is used and every call still resolves.
function Emitter:callee_instance(target,block,block_id,position,arguments)
    local generic=self:generic_instance(target)
    if self:self_tail_recursive(target) then return generic end
    local seeded={Known.runtime(B.Effect)}
    local useful=false
    for i,ref in ipairs(arguments) do
        local answer=self.current_instance.analysis:resolve(block,block_id,position,ref)
        seeded[i+1]=answer
        if Known.is_known(answer) then useful=true end
    end
    if not useful then return generic end
    return self:specialized_instance(target,seeded) or generic
end

-- The instance for a packet, if one can be built: nil when the budget is spent or the same
-- instance is already being analysed, which is how a cycle terminates.
function Emitter:specialized_instance(id,seeded)
    local key=self.run:key(id,seeded)
    local existing=self.instances[key]
    if existing then return existing end
    local analysis=self.run:instance(id,seeded)
    if not analysis then return nil end
    return self:add_instance(id,analysis,key,false)
end

-- What a function's body needs, as one set of producer positions and outputs. The demand pass
-- over its instructions, plus the entry parameters block 1 reads.
--
-- The second part is not redundant. The demand pass reports the module unload's state -- which
-- a `Destroy` consumes -- as unneeded, so its answer for an entry packet cannot be used on its
-- own. The scan is local to block 1 on purpose: anything read in another block was copied
-- there by an edge, and that copy is itself a reference, so a parameter block 1 never reads is
-- one nothing reads. It is recomputed per belt rather than cached beside the demand table,
-- because a callee and its call sites must reach the same answer.
local requirements={}
-- The parameters block 1 reads. A call argument counts as a use only when the callee's parameter
-- is live: a dead parameter is dropped from the callee's signature and from the call, so treating
-- the argument as a use would keep the caller's parameter alive for a value never passed. One
-- rule reaches both. On a cycle the callee is still being computed, so its parameters are live.
function Emitter:entry_parameters_read(belt)
    local block=belt.blocks[1]
    local used={}
    local function note(position,ref)
        local producer=block:resolve(position,ref)
        if producer<#block.parameters then used[producer]=true end
    end
    for index,instruction in ipairs(block.instructions) do
        local at=#block.parameters+index-1
        local operation=instruction.operation
        local callee=B.CallFunction:isclassof(operation) and self.functions[operation.target]
        if callee and requirements[callee]~='pending' then
            for i,ref in ipairs(operation.arguments) do
                if self:parameter_live(nil,callee,1,i+1) then note(at,ref) end
            end
        else
            for _,ref in ipairs(operation:inputs()) do note(at,ref) end
        end
    end
    local at=#block.parameters+#block.instructions
    for _,ref in ipairs(block.exit:inputs()) do note(at,ref) end
    return used
end

function Emitter:requirements(belt)
    local cached=requirements[belt]
    if cached then return cached end
    requirements[belt]='pending'
    local needed=belt:demands()
    local read=self:entry_parameters_read(belt)
    needed[1]=needed[1] or {}
    for position in pairs(read) do
        needed[1][position]=needed[1][position] or {}
        needed[1][position][0]=true
    end
    -- Block 1's read set is the whole story for its parameters, so a parameter no instruction
    -- reads is not needed, even though the demand pass marked it as a call argument.
    for position=0,#belt.blocks[1].parameters-1 do
        if not read[position] then
            local entry=needed[1][position]
            if entry then entry[0]=nil end
        end
    end
    requirements[belt]=needed
    return needed
end

-- What happens to one output of one producer.
--   'constant' -- its value is known, so every use of it is that constant;
--   'value'    -- it is materialized, and uses read it by name;
--   'dropped'  -- nothing needs it, so neither it nor its producer is written out.
--
-- A parameter asks the same question with `position` being its 0-based index, which is where
-- its value lives in the entry packet.
-- Whether a function is part of the program's interface to its host: the module initializer and
-- the entry points published for the host to call. Both are named for the linker rather than
-- `static`, and that is a property of the program, not of anything a caller passes in.
function Emitter:hosted(instance)
    return instance.id==1 or (self.host_ids and self.host_ids[instance.id]==true)
end

function Emitter:disposition(analysis,belt,block_id,position,output)
    local block=belt.blocks[block_id]
    local parameter=block.parameters[position+1]
    -- An effect is not a value and never a declaration; it exists to order the body.
    if parameter and parameter.type==B.Effect then return 'value' end
    -- A parameter's value is the packet the caller supplied; an instruction's is its own
    -- result. That is the only difference between the two, so it is stated here.
    local answer
    if parameter then answer=analysis and analysis:param(block_id,position+1)
    else answer=analysis and analysis:answer(block_id,position,output) end
    if Known.is_known(answer) then return 'constant',answer end
    local needed=self:requirements(belt)[block_id]
    if needed and needed[position] and needed[position][output] then return 'value' end
    return 'dropped'
end

-- Whether an instruction is written out at all. A call the evaluator folded is not, and a
-- pure producer whose outputs are all dropped is not either.
function Emitter:instruction_runs(analysis,belt,block_id,position,instruction)
    if analysis and B.CallFunction:isclassof(instruction.operation)
        and analysis:call_was_folded(block_id,position) then return false end
    for output=0,#instruction.results-1 do
        if self:disposition(analysis,belt,block_id,position,output)~='dropped' then return true end
    end
    return false
end

-- Does this parameter of this block exist in C at all? The function's signature, every call
-- site and every edge copy ask here, so they cannot disagree. An effect never does: statement
-- order carries it, so it is neither declared, nor passed, nor copied.
function Emitter:parameter_live(analysis,belt,block_id,index)
    if belt.blocks[block_id].parameters[index].type==B.Effect then return false end
    return self:disposition(analysis,belt,block_id,index-1,0)=='value'
end

function Emitter:needed_parameter(block_id,index)
    return self:parameter_live(self.current_instance.analysis,self.current,block_id,index)
end

-- The arguments a call passes: belt argument i lands on entry parameter i+1, the effect being
-- carried separately.
-- The arguments a call passes, asked of the instance it names: belt argument i lands on entry
-- parameter i+1, and the effect is carried separately. Signature and call site ask the same
-- rule of the same instance, so they cannot disagree.
function Emitter:call_arguments(instance,block,block_id,position,refs)
    local out=L()
    for i,ref in ipairs(refs) do
        if self:parameter_live(instance.analysis,instance.belt,1,i+1) then
            out:insert(self:ref(block,block_id,position,ref))
        end
    end
    return out
end

-- Edge packets are parallel assignments, so a temporary breaks any clobber cycle.
function Emitter:edge(target_id,edge,block,block_id,position)
    local target=self.current.blocks[target_id]
    local statements=L()
    local temporaries=L()
    local live={}
    for i,ref in ipairs(edge.arguments) do
        if self:needed_parameter(target_id,i) then
            local name=self:value(block_id,position,'e' .. i)
            live[#live+1]=i
            temporaries:insert(C.Declare(self:ctype(target.parameters[i].type),name,self:ref(block,block_id,position,ref)))
        end
    end
    statements:insertall(temporaries)
    for _,i in ipairs(live) do
        statements:insert(C.Assign(C.Name(self:param(target_id,i-1)),C.Name(self:value(block_id,position,'e' .. i))))
    end
    statements:insert(C.Goto('b' .. target_id))
    return C.Block(statements)
end

function Emitter:exit(target_id,block,block_id,exit)
    local position=#block.parameters+#block.instructions
    if B.Return:isclassof(exit) then
        local types=self.functions[target_id].signature.results
        local given=self:arglist(block,block_id,position,exit.values)
        local values=L()
        for i,type_ in ipairs(types) do if type_~=B.Effect then values:insert(given[i]) end end
        local type_=self:return_shape(types)
        return C.Return(self:return_value(type_,values))
    elseif B.Jump:isclassof(exit) then
        return self:edge(exit.edge.target,exit.edge,block,block_id,position)
    elseif B.Branch:isclassof(exit) then
        local taken=self.decision[block_id]
        if taken then return self:edge(taken.target,taken,block,block_id,position) end
        local condition=self:ref(block,block_id,position,exit.condition)
        return C.If(condition,self:edge(exit.yes.target,exit.yes,block,block_id,position),self:edge(exit.no.target,exit.no,block,block_id,position))
    elseif B.TailCall:isclassof(exit) then
        local arguments=self:arglist(block,block_id,position,exit.arguments)
        if exit.target==target_id then
            -- A self tail transfer reuses this activation: assign the entry packet and
            -- jump back to the entry block instead of growing a continuation chain.
            local entry=self.current.blocks[1]
            local statements,live=L(),{}
            -- A tail call's arguments exclude the effect, so argument i lands on belt
            -- parameter i+1 (1-based for the packet, 0-based for the C name).
            for i,argument in ipairs(exit.arguments) do
                if self:needed_parameter(1,i+1) then
                    local name=self:value(block_id,position,'t' .. i)
                    live[#live+1]=i
                    statements:insert(C.Declare(self:ctype(entry.parameters[i+1].type),name,self:ref(block,block_id,position,argument)))
                end
            end
            for _,i in ipairs(live) do statements:insert(C.Assign(C.Name(self:param(1,i)),C.Name(self:value(block_id,position,'t' .. i)))) end
            statements:insert(C.Goto('b1'))
            return C.Block(statements)
        end
        local callee=self:callee_instance(exit.target,block,block_id,position,exit.arguments)
        return C.Return(C.Call(C.Name(callee.name),
            self:call_arguments(callee,block,block_id,position,exit.arguments)))
    elseif B.Trap:isclassof(exit) then
        self.trap=true
        local statements=L()
        statements:insert(C.Evaluate(C.Call(C.Name('let_trap'),L{C.String(exit.reason)})))
        local type_=self:return_shape(self.functions[target_id].signature.results)
        statements:insert(C.Return(type_==C.Void and nil or C.Integer(0,0)))
        return C.Block(statements)
    end
    self:error('no representation for ' .. tostring(exit))
end

-- C names come from the belt: the module initializer and each word entry by its source
-- name, so a reader can tell what a function is without a legend.
local function sanitize(name)
    name=name:gsub('[^%w_]','_')
    if name:match('^%d') then name='w' .. name end
    return name
end

function Emitter:function_name(id)
    local name=self.program.functions[id] and self.program.functions[id].name
    if name=='__module_init' then return 'let_module_init' end
    if name=='__module_unload' then return 'let_module_unload' end
    return 'let_' .. sanitize(name or ('fn_' .. id))
end

-- The signature of an instance, asked through the same rule a call site uses, so the two
-- cannot disagree about what is passed.
function Emitter:function_parameters_for(instance)
    local belt=instance.belt
    local parameters=L()
    for i,parameter in ipairs(belt.blocks[1].parameters) do
        if self:parameter_live(instance.analysis,belt,1,i) then
            parameters:insert(C.Parameter(self:ctype(parameter.type),self:param(1,i-1)))
        end
    end
    return parameters
end

function Emitter:emit_instance(instance)
    local belt,analysis=instance.belt,instance.analysis
    -- A fully folded function has no residual work at all, so its body is the constant it
    -- computes. Nothing inside it is walked: no blocks, no labels, no gotos.
    if analysis.folded then
        local type_=self:return_shape(belt.signature.results)
        local values=L()
        for i,result in ipairs(belt.signature.results) do
            if result~=B.Effect then values:insert(self:constant(analysis.results[i])) end
        end
        local external=self:hosted(instance)
        return C.Function(instance.name,external,external,type_,
            self:function_parameters_for(instance),
            C.Block(L{C.Return(self:return_value(type_,values))}))
    end
    self.current_instance=instance
    self.current=belt
    self.current_id=instance.id
    self.live=analysis.live_blocks
    self.decision=analysis.decision
    -- Consumer demand is a frontend decision: an unneeded pure producer is never
    -- written out, so the emitted C does not rely on a C compiler to delete it.
    -- Ordered operations always carry a demanded effect output and are therefore kept.
    local result=self:return_shape(belt.signature.results)
    local parameters=self:function_parameters_for(instance)
    local body=L()
    -- Non-entry block parameters are assigned only by edges, so they are declared once.
    -- The entry block's packet is the function's ABI and is never pruned.
    for block_id=2,#belt.blocks do
        for i,parameter in ipairs(belt.blocks[block_id].parameters) do
            if self:needed_parameter(block_id,i) then
                body:insert(C.Declare(self:ctype(parameter.type),self:param(block_id,i-1),nil))
            end
        end
    end
    body:insert(C.Goto('b1'))
    for block_id,block in ipairs(belt.blocks) do
        if not self.live[block_id] then goto continue_block end
        body:insert(C.Label('b' .. block_id))
        for index,instruction in ipairs(block.instructions) do
            local position=#block.parameters+index-1
            if self:instruction_runs(analysis,belt,block_id,position,instruction) then
                body:insertall(self:instruction(block,block_id,index,instruction))
            end
        end
        body:insert(self:exit(instance.id,block,block_id,block.exit))
        ::continue_block::
    end
    local external=self:hosted(instance)
    return C.Function(instance.name,external,external,result,parameters,C.Block(body))
end

-- Resources and hosts are foreign code: the emitter declares the symbols it calls, and
-- the embedding supplies the implementations.
function Emitter:host_declarations()
    local declarations=L()
    local names={}
    -- Symbol sources are Lua tables, so sort them: an emitted unit must not depend on
    -- `pairs` order, or two builds of one program would differ byte for byte.
    -- A destructor is declared only when a `Destroy` names it, for the same reason hosts are: a
    -- registered resource the program does not use must not appear in its C.
    local destroys={}
    for symbol in pairs(self.used_destroys) do destroys[#destroys+1]=symbol end
    table.sort(destroys)
    for _,symbol in ipairs(destroys) do
        -- A resource that is a C pointer is destroyed through that pointer; a handle stays an
        -- integer. The representation belongs to the resource, not to the destructor's spelling.
        local type_=self.destroy_pointer[symbol] and C.Pointer(C.Named('void')) or C.I64
        declarations:insert(C.Function(symbol,true,false,C.Void,L{C.Parameter(type_,'a0')},nil))
    end
    local symbols={}
    -- Only a host the program actually calls is declared: a vocabulary may be registered for
    -- names a program does not use, and those must not appear in its C.
    for _,host in pairs(self.used_hosts) do
        if not names[host.symbol] then names[host.symbol]=true; symbols[#symbols+1]=host.symbol end
    end
    table.sort(symbols)
    for _,symbol in ipairs(symbols) do
        local host=self.hosts[symbol]
        -- A declared prototype may name `size_t` or `ptrdiff_t`, so the includes follow the
        -- hosts actually written out, not every registered one.
        if host.c then self.c_hosts=true end
        local parameters=L()
        for i,parameter in ipairs(host.signature.parameters) do
            local spelling=host.c and host.c.params and host.c.params[i]
            local type_
            if spelling then type_=C.Named(spelling)
            else type_=parameter.capability==A.Mut and C.Pointer(self:ctype(parameter.type)) or self:ctype(parameter.type) end
            parameters:insert(C.Parameter(type_,'a' .. i))
        end
        local result=host.signature.results[1]
        local result_type
        if host.c and host.c.result then result_type=C.Named(host.c.result)
        else result_type=result==B.Unit and C.Void or self:ctype(result) end
        declarations:insert(C.Function(host.symbol,true,false,result_type,parameters,nil))
    end
    return declarations
end

function Emitter:helper_declarations()
    local declarations=L()
    if self.text or self.helpers.text_eq or self.helpers.text_from_c then declarations:insert(C.Struct('let_text',L{C.Parameter(C.Pointer(C.Named('char')),'data'),C.Parameter(C.U64,'size')})) end
    declarations:insert(C.Function('let_trap',true,false,C.Void,L{C.Parameter(C.Pointer(C.Named('char')),'reason')},nil))
    local function raw(code) declarations:insert(C.Raw(code)) end
    -- A `char*` the host returns has no length; the Let Text takes its size from the bytes up
    -- to the terminator, which is the contract a C string already implies.
    if self.helpers.text_from_c then raw('static struct let_text let_text_from_c(const char* s){struct let_text t;t.data=(char*)s;t.size=s?(size_t)strlen(s):0;return t;}') end
    -- Signed overflow is undefined in C, so wrapping arithmetic must go through unsigned.
    -- These are one-line and branch-free, so a macro inlines them without adding a function.
    if self.helpers.add then raw('#define LET_ADD(a,b) ((int64_t)((uint64_t)(a)+(uint64_t)(b)))') end
    if self.helpers.sub then raw('#define LET_SUB(a,b) ((int64_t)((uint64_t)(a)-(uint64_t)(b)))') end
    if self.helpers.mul then raw('#define LET_MUL(a,b) ((int64_t)((uint64_t)(a)*(uint64_t)(b)))') end
    if self.helpers.neg then raw('#define LET_NEG(a) ((int64_t)(0-(uint64_t)(a)))') end
    -- Division and remainder keep one shared helper each: inlining the trap check at every
    -- site would duplicate control flow rather than remove a function.
    if self.helpers.div then raw('static int64_t let_div(int64_t a,int64_t b){if(b==0)let_trap("division by zero");if(b==-1)return (int64_t)(0-(uint64_t)a);return a/b;}') end
    if self.helpers.rem then raw('static int64_t let_rem(int64_t a,int64_t b){if(b==0)let_trap("remainder by zero");if(b==-1)return 0;return a%b;}') end
    -- The conversion is total (§13.3): a NaN becomes zero and an out-of-range value saturates at
    -- the nearer Int bound, so it needs no effect and can be folded or dropped.
    if self.helpers.to_int then raw('static int64_t let_to_int(double x){if(x!=x)return 0;if(x>=9223372036854775808.0)return INT64_MAX;if(x<-9223372036854775808.0)return INT64_MIN;return (int64_t)x;}') end
    if self.helpers.text_eq then raw('#define LET_TEXT_EQ(a,b) ((a).size==(b).size&&memcmp((a).data,(b).data,(size_t)(a).size)==0)') end
    return declarations
end

-- What was emitted, for a caller that wants to know rather than guess: one entry per
-- instance, with the ABI it ended up with, and how stable the analysis that produced it was.
-- `widened` counts packet fields the fixed point had to forget, which is the honest measure of
-- how much precision a loop cost.
function Emitter:report(statistics)
    statistics.instances={}
    local specialized,folded,widened=0,0,0
    for _,instance in ipairs(self.pending) do
        local analysis=instance.analysis
        local parameters={}
        for i,parameter in ipairs(instance.belt.blocks[1].parameters) do
            if self:parameter_live(analysis,instance.belt,1,i) then
                parameters[#parameters+1]=tostring(parameter.type)
            end
        end
        local blocks=0
        for _ in pairs(analysis.live_blocks or {}) do blocks=blocks+1 end
        local forgotten=0
        for _ in pairs(analysis.widened or {}) do forgotten=forgotten+1 end
        widened=widened+forgotten
        if not instance.generic then specialized=specialized+1 end
        if analysis.folded then folded=folded+1 end
        statistics.instances[#statistics.instances+1]={name=instance.name,id=instance.id,
            generic=instance.generic,folded=analysis.folded==true,parameters=parameters,
            blocks=blocks,widened=forgotten}
    end
    -- What the host must pass, which only the emitter knows: a field whose fate is not `value`
    -- is not a parameter -- a constant is materialized inside the entry -- so the fields the host
    -- supplies are those the signature kept, in their own order, followed by the stages.
    statistics.entries={}
    for _,entry in ipairs(self.options.entries or {}) do
        local instance=self.generic[entry.id]
        local fields,stages={},0
        if instance then
            local belt=instance.belt
            -- The entry's parameters are its effect first, then the fields, then the stages.
            for i=1,entry.bundle do
                if self:parameter_live(instance.analysis,belt,1,i+1) then fields[#fields+1]=i-1 end
            end
            -- The same rule for the stages: one the body never reads is not in the signature, so
            -- the host does not supply it. A generic instance never has a *constant* parameter, so
            -- a stage left out here is one nothing reads.
            for i=entry.bundle+1,#belt.blocks[1].parameters-1 do
                if self:parameter_live(instance.analysis,belt,1,i+1) then stages=stages+1 end
            end
        end
        statistics.entries[#statistics.entries+1]={name=entry.name,id=entry.id,
            c_name=instance and instance.name or nil,fields=fields,stages=stages}
    end
    statistics.specialized=specialized
    statistics.folded=folded
    statistics.widened=widened
    statistics.functions=#self.pending
    return statistics
end

function Emitter:program(program,options)
    self.statics=L()
    self.program=program
    self.functions=program.functions
    -- Symbols to declare and call, from the top-level hosts and from any namespace member that
    -- is a host (`c.puts`).
    self.hosts={}
    for _,host in pairs(options.hosts or {}) do self.hosts[host.symbol]=host end
    for _,descriptor in pairs(options.resources or {}) do
        self.destroy_pointer[descriptor.destroy]=descriptor.representation=='pointer'
    end
    for _,namespace in pairs(options.dictionary or {}) do
        for _,member in pairs(namespace.members or {}) do
            if member.signature then self.hosts[member.symbol]=member end
        end
    end
    -- One shared run: an instance is analysed once and reused by every call site that asks
    -- for the same entry packet.
    self.run=Known.run(program,options)
    -- Which entries the host publishes. The host selects (§15.1); a command-line compiler is a
    -- host that selects every exported word, and says so by passing them.
    self.host_ids={}
    for _,entry in ipairs(options.entries or {}) do self.host_ids[entry.id]=true end
    -- The module interface is the root of the instance graph, and emission discovers the rest
    -- by writing the calls it finds -- which is the same discovery that decides liveness.
    self:generic_instance(1)
    self:generic_instance(2)
    -- A host entry has no caller inside the belt, so nothing would make it live: the entries the
    -- program publishes as its host interface are roots, like the module interface itself.
    for _,entry in ipairs(options.entries or {}) do self:generic_instance(entry.id) end
    local functions=L()
    local at=1
    while self.pending[at] do
        functions:insert(self:emit_instance(self.pending[at]))
        at=at+1
    end
    if options.statistics then self:report(options.statistics) end
    local host_declarations=self:host_declarations()
    local helpers=self:helper_declarations()
    -- A host that declares its C prototype may name `size_t` or `ptrdiff_t` (§15.3); a program
    -- that does not keeps the smaller include set.
    local includes=L()
    if self.c_hosts then includes:insert('stddef.h') end
    includes:insert('stdint.h'); includes:insert('stdbool.h')
    if self.text and (self.helpers.text_eq or self.helpers.text_from_c) then includes:insert('string.h') end
    if self.math then includes:insert('math.h') end
    local declarations=L()
    declarations:insertall(helpers)
    declarations:insertall(self.statics)
    for _,struct in ipairs(self.structs) do declarations:insert(struct) end
    for _,struct in ipairs(self.results) do declarations:insert(struct) end
    declarations:insertall(host_declarations)
    for _,instance in ipairs(self.pending) do
        declarations:insert(C.Function(instance.name,self:hosted(instance),self:hosted(instance),
            self:return_shape(instance.belt.signature.results),
            self:function_parameters_for(instance),nil))
    end
    declarations:insertall(functions)
    return C.Unit(includes,declarations)
end

function B.Program:emit(options)
    options=options or {}
    local emitter=Emitter.new(options)
    return emitter:program(self,options)
end
end

end)

-- let/cli.lua
module('let.cli', function(require, ...)
-- The command-line host: compiles one file to C, and to a complete C program when the file
-- exports a word named `main` that still needs no stage. It is a host, not the compiler: it
-- chooses the vocabulary (libc, then the embedding's, so the embedding wins) and the entry,
-- which is what §15.1 leaves to the embedding.
return function(V,arg)
    arg = arg or {}

    -- An exported word named `main` that needs no stage is the program's entry.
    local function entry(builder)
        for _,candidate in ipairs(builder.host_entries or {}) do
            if candidate.name=='main' and candidate.stages==0 then
                -- The generated `main` passes the word's own fields from the namespace, and that
                -- mapping is not published yet; a closed word needs none.
                assert(candidate.bundle==0,'a `main` entry may not capture module state yet')
                return candidate
            end
        end
    end

    -- A complete C program: the module initializer, then the entry, plus the trap hook an
    -- executable must provide. `statistics` carries the entry's C name and the namespace members
    -- it takes as parameters.
    local function executable(unit,statistics)
        local namespace
        for _,declaration in ipairs(unit.declarations) do
            if V.C.Function:isclassof(declaration) and declaration.name=='let_module_init' then
                namespace=declaration.result
            end
        end
        local main
        for _,candidate in ipairs(statistics.entries or {}) do
            if candidate.name=='main' then main=candidate end
        end
        if not (namespace and main and main.c_name) then return unit end
        local arguments={}
        for _,field in ipairs(main.fields) do arguments[#arguments+1]=('ns.r0.f%d'):format(field) end
        local declarations=V.List()
        for _,declaration in ipairs(unit.declarations) do declarations:insert(declaration) end
        declarations:insert(V.C.Raw('void let_trap(char* reason){ fputs(reason,stderr); fputc(10,stderr); abort(); }'))
        declarations:insert(V.C.Raw(('int main(void){ %s ns = let_module_init(); %s(%s); return 0; }')
            :format(namespace:print(),main.c_name,table.concat(arguments,', '))))
        local includes,seen=V.List(),{}
        for _,include in ipairs(unit.includes) do includes:insert(include); seen[include]=true end
        for _,include in ipairs{'stdio.h','stdlib.h'} do
            if not seen[include] then includes:insert(include) end
        end
        return V.C.Unit(includes,declarations)
    end

    local function compile(input,output,options_path)
        local file=assert(io.open(input,'rb'))
        local text=file:read('*a'); file:close()
        local options=options_path and dofile(options_path) or {}
        -- The C vocabulary is a namespace, so it cannot collide with a program's own names;
        -- an embedding or options file that declares `c` itself wins.
        local dictionary=options.dictionary or {}
        if not dictionary.c then dictionary.c={members=V.libc.members} end
        options.dictionary=dictionary
        -- The C memory resource is the CLI's, and the embedding's own resources still win.
        local resources={}
        for name,descriptor in pairs(V.libc.resources or {}) do resources[name]=descriptor end
        for name,descriptor in pairs(options.resources or {}) do resources[name]=descriptor end
        options.resources=resources
        options.dictionary=dictionary
        local program,builder=V.parse(text,input):build(options)
        -- This is a host, and it publishes every exported word: §15.1's "the host selects".
        options.entries=options.entries or builder.host_entries
        options.statistics=options.statistics or {}
        local unit=program:emit(options)
        if entry(builder) then unit=executable(unit,options.statistics) end
        local source=V.print(unit)
        if output then
            local out=assert(io.open(output,'wb')); out:write(source); out:close()
        else io.write(source) end
    end

    local ok,err=pcall(function()
        if not arg[1] or #arg>3 then
            error('usage: luajit letc.lua input.let [output.c [options.lua]]',0)
        end
        compile(arg[1],arg[2],arg[3])
    end)
    if not ok then io.stderr:write(tostring(err),'\n'); os.exit(1) end
end

end)

local V = require('let')
-- Run as a script rather than required: compile arg[1] to arg[2], or to stdout.
local this, script = debug.getinfo(1, 'S').short_src, arg and arg[0]
-- Run as a script rather than required: compile arg[1] to arg[2], or to stdout. The test is
-- whether this chunk *is* the running script; loading it into another program is not.
if script and this == script then
    require('let.cli')(V, arg)
else
    return V
end
